            feya_commerce_seo_keyword_metric_import_staging_v1.competition,
            feya_commerce_seo_keyword_metric_import_staging_v1.competition_index,
            feya_commerce_seo_keyword_metric_import_staging_v1.low_top_of_page_bid,
