          ORDER BY feya_commerce_seo_keyword_metric_import_staging_v1.keyword_norm, feya_commerce_seo_keyword_metric_import_staging_v1.imported_at DESC NULLS LAST, feya_commerce_seo_keyword_metric_import_staging_v1.import_row_id DESC
        )
