            ((e.match_text ~~ '%gold%'::text) OR (e.match_text ~~ '%silver%'::text) OR (e.match_text ~~ '%mirror%'::text) OR (e.match_text ~~ '%metallic%'::text) OR (e.match_text ~~ '%reflective%'::text) OR (e.match_text ~~ '%holographic%'::text) OR (e.match_text ~~ '%chrome%'::text) OR (e.match_text ~~ '%leather%'::text) OR (e.match_text ~~ '%faux leather%'::text) OR (e.match_text ~~ '%acrylic%'::text) OR (e.match_text ~~ '%black%'::text) OR (e.match_text ~~ '%white%'::text) OR (e.match_text ~~ '%iridescent%'::text) OR (e.match_text ~~ '%shiny%'::text)) AS has_material_color,
            ((e.match_text ~~ '%price%'::text) OR (e.match_text ~~ '%cost%'::text) OR (e.match_text ~~ '%shipping%'::text) OR (e.match_text ~~ '%delivery%'::text) OR (e.match_text ~~ '%size%'::text) OR (e.match_text ~~ '%sizing%'::text) OR (e.match_text ~~ '%how to%'::text) OR (e.match_text ~~ '%what to wear%'::text)) AS is_faq_intent,
            ((e.match_text ~~ '%buy%'::text) OR (e.match_text ~~ '%shop%'::text) OR (e.match_text ~~ '%order%'::text) OR (e.match_text ~~ '%custom%'::text) OR (e.match_text ~~ '%handmade%'::text) OR (e.match_text ~~ '%for sale%'::text) OR (e.match_text ~~ '%online%'::text) OR (e.match_text ~~ '%website%'::text) OR (e.match_text ~~ '%store%'::text)) AS is_commercial_intent,
            ((e.match_text ~~ '%rave%'::text) OR (e.match_text ~~ '%edm%'::text) OR (e.match_text ~~ '%festival%'::text) OR (e.match_text ~~ '%burning man%'::text) OR (e.match_text ~~ '%coachella%'::text) OR (e.match_text ~~ '%stage%'::text) OR (e.match_text ~~ '%performance%'::text) OR (e.match_text ~~ '%drag%'::text) OR (e.match_text ~~ '%clubwear%'::text) OR (e.match_text ~~ '%dancer%'::text) OR (e.match_text ~~ '%dance%'::text) OR (e.match_text ~~ '%futuristic%'::text) OR (e.match_text ~~ '%cyberpunk%'::text) OR (e.match_text ~~ '%apocalyptic%'::text) OR (e.match_text ~~ '%post apocalyptic%'::text) OR (e.match_text ~~ '%desert%'::text) OR (e.match_text ~~ '%cosmic%'::text) OR (e.match_text ~~ '%sci fi%'::text) OR (e.match_text ~~ '%sci-fi%'::text) OR (e.match_text ~~ '%punk%'::text) OR (e.match_text ~~ '%glam%'::text) OR (e.match_text ~~ '%warrior%'::text)) AS has_event_style,
            to_jsonb(array_remove(ARRAY[
                CASE
                    WHEN ((e.match_text ~~ '%lego%'::text) OR (e.match_text ~~ '%pokemon%'::text) OR (e.match_text ~~ '%pokémon%'::text) OR (e.match_text ~~ '%barbie%'::text) OR (e.match_text ~~ '%disney%'::text) OR (e.match_text ~~ '%wonder woman%'::text) OR (e.match_text ~~ '%batman%'::text) OR (e.match_text ~~ '%harry potter%'::text) OR (e.match_text ~~ '%star wars%'::text) OR (e.match_text ~~ '%mandalorian%'::text) OR (e.match_text ~~ '%spongebob%'::text) OR (e.match_text ~~ '%shrek%'::text) OR (e.match_text ~~ '%my little pony%'::text)) THEN 'franchise_brand'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%kids%'::text) OR (e.match_text ~~ '% child%'::text) OR (e.match_text ~~ '%children%'::text) OR (e.match_text ~~ '%baby%'::text) OR (e.match_text ~~ '%toddler%'::text) OR (e.match_text ~~ '%dog costume%'::text) OR (e.match_text ~~ '%pet costume%'::text)) THEN 'kids_pet'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%diy%'::text) OR (e.match_text ~~ '%pattern%'::text) OR (e.match_text ~~ '%template%'::text) OR (e.match_text ~~ '%sewing pattern%'::text) OR (e.match_text ~~ '%make your own%'::text)) THEN 'diy_pattern'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%bridal%'::text) OR (e.match_text ~~ '%bride%'::text) OR (e.match_text ~~ '%wedding%'::text) OR (e.match_text ~~ '%bridesmaid%'::text) OR (e.match_text ~~ '%prom%'::text) OR (e.match_text ~~ '%homecoming%'::text) OR (e.match_text ~~ '%flapper%'::text) OR (e.match_text ~~ '%gatsby%'::text) OR (e.match_text ~~ '%renaissance%'::text) OR (e.match_text ~~ '%medieval%'::text)) THEN 'wrong_occasion'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%n95%'::text) OR (e.match_text ~~ '%kn95%'::text) OR (e.match_text ~~ '%surgical mask%'::text) OR (e.match_text ~~ '%medical mask%'::text) OR (e.match_text ~~ '%respirator%'::text) OR (e.match_text ~~ '%dust mask%'::text) OR (e.match_text ~~ '%gas mask%'::text) OR (e.match_text ~~ '%protective face mask%'::text)) THEN 'medical_safety'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%fall protection%'::text) OR (e.match_text ~~ '%safety harness%'::text) OR (e.match_text ~~ '%climbing harness%'::text) OR (e.match_text ~~ '%wire harness%'::text) OR (e.match_text ~~ '%wiring harness%'::text) OR (e.match_text ~~ '%osha%'::text) OR (e.match_text ~~ '%ansi%'::text) OR (e.match_text ~~ '%lanyard%'::text)) THEN 'industrial_harness'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%necklace%'::text) OR (e.match_text ~~ '%earrings%'::text) OR (e.match_text ~~ '%diamond%'::text) OR (e.match_text ~~ '%pearl jewelry%'::text)) THEN 'jewelry_only'::text
                    ELSE NULL::text
                END], NULL::text)) AS block_flags
           FROM enriched e
        ), bucketed AS (
         SELECT f.candidate_keyword,
            f.candidate_keyword_norm,
            f.candidate_source,
            f.source_batch,
            f.source_row_type,
            f.avg_monthly_searches,
            f.competition,
            f.competition_index,
            f.low_bid,
            f.high_bid,
            f.bid_currency,
            f.metric_source,
            f.metric_date,
            f.source_review_status,
            f.source_validation_status,
            f.cleanup_pipeline_status,
            f.source_bank_bucket,
            f.source_page_type,
            f.source_role,
            f.source_role_label,
            f.source_clusters,
            f.source_files,
            f.source_reason,
            f.source_notes,
            f.raw_json,
            f.source_priority,
            f.rn,
            f.exists_in_bank,
            f.exists_in_listing_master,
            f.bank_review_status,
            f.bank_bucket,
            f.match_text,
            f.has_metric,
            f.has_usable_metric,
            f.is_no_metric_unknown,
            f.has_component,
            f.has_material_color,
            f.is_faq_intent,
            f.is_commercial_intent,
            f.has_event_style,
            f.block_flags,
                CASE
                    WHEN f.is_faq_intent THEN 'faq'::text
                    WHEN f.is_commercial_intent THEN 'commercial_collection'::text
                    WHEN (f.has_component AND f.has_material_color) THEN 'product_or_alt'::text
                    WHEN f.has_component THEN 'product'::text
                    WHEN (f.has_material_color AND ((f.match_text ~~ '%outfit%'::text) OR (f.match_text ~~ '%costume%'::text) OR (f.match_text ~~ '%dress%'::text) OR (f.match_text ~~ '% set%'::text))) THEN 'visual_collection'::text
                    WHEN f.has_event_style THEN 'collection'::text
                    ELSE 'hold'::text
                END AS proposed_bank_bucket
           FROM flags f
        ), decided AS (
         SELECT b.candidate_keyword,
            b.candidate_keyword_norm,
            b.candidate_source,
            b.source_batch,
            b.source_row_type,
            b.avg_monthly_searches,
            b.competition,
            b.competition_index,
            b.low_bid,
            b.high_bid,
            b.bid_currency,
            b.metric_source,
            b.metric_date,
            b.source_review_status,
            b.source_validation_status,
            b.cleanup_pipeline_status,
            b.source_bank_bucket,
            b.source_page_type,
            b.source_role,
            b.source_role_label,
            b.source_clusters,
            b.source_files,
            b.source_reason,
            b.source_notes,
            b.raw_json,
            b.source_priority,
            b.rn,
            b.exists_in_bank,
            b.exists_in_listing_master,
            b.bank_review_status,
            b.bank_bucket,
            b.match_text,
            b.has_metric,
            b.has_usable_metric,
            b.is_no_metric_unknown,
            b.has_component,
            b.has_material_color,
            b.is_faq_intent,
            b.is_commercial_intent,
            b.has_event_style,
            b.block_flags,
            b.proposed_bank_bucket,
                CASE
                    WHEN (jsonb_array_length(b.block_flags) > 0) THEN 'reject'::text
                    WHEN b.exists_in_bank THEN b.bank_review_status
                    WHEN (b.source_row_type = 'google_ads_related_idea'::text) THEN 'hold'::text
                    WHEN (NOT b.has_usable_metric) THEN 'hold'::text
                    WHEN (b.proposed_bank_bucket = 'hold'::text) THEN 'hold'::text
                    WHEN ((COALESCE(b.avg_monthly_searches, 0) = 0) AND ((b.competition IS NULL) OR (upper(b.competition) = 'UNKNOWN'::text))) THEN 'hold'::text
                    ELSE 'approved_draft'::text
                END AS proposed_review_status
           FROM bucketed b
        ), actioned AS (
         SELECT d.candidate_keyword,
            d.candidate_keyword_norm,
            d.candidate_source,
            d.source_batch,
            d.source_row_type,
            d.avg_monthly_searches,
            d.competition,
            d.competition_index,
            d.low_bid,
            d.high_bid,
            d.bid_currency,
            d.metric_source,
            d.metric_date,
            d.source_review_status,
            d.source_validation_status,
            d.cleanup_pipeline_status,
            d.source_bank_bucket,
            d.source_page_type,
            d.source_role,
            d.source_role_label,
            d.source_clusters,
            d.source_files,
            d.source_reason,
            d.source_notes,
            d.raw_json,
            d.source_priority,
            d.rn,
            d.exists_in_bank,
            d.exists_in_listing_master,
            d.bank_review_status,
            d.bank_bucket,
            d.match_text,
            d.has_metric,
            d.has_usable_metric,
            d.is_no_metric_unknown,
            d.has_component,
            d.has_material_color,
            d.is_faq_intent,
            d.is_commercial_intent,
            d.has_event_style,
            d.block_flags,
            d.proposed_bank_bucket,
            d.proposed_review_status,
                CASE
                    WHEN d.exists_in_bank THEN 'excluded_duplicate'::text
                    WHEN (jsonb_array_length(d.block_flags) > 0) THEN 'excluded_noise'::text
                    WHEN (d.source_row_type = 'google_ads_related_idea'::text) THEN 'needs_manual_review_related_idea'::text
                    WHEN (NOT d.has_usable_metric) THEN 'needs_manual_review_no_metric'::text
                    WHEN (d.proposed_bank_bucket = 'hold'::text) THEN 'needs_manual_review_bucket'::text
                    WHEN ((COALESCE(d.avg_monthly_searches, 0) = 0) AND ((d.competition IS NULL) OR (upper(d.competition) = 'UNKNOWN'::text))) THEN 'needs_manual_review_zero_metric'::text
                    ELSE 'would_insert'::text
                END AS dry_run_action
           FROM decided d
        )
 SELECT candidate_keyword,
    candidate_keyword_norm,
    candidate_source,
    source_batch,
    source_row_type,
    exists_in_bank,
    exists_in_listing_master,
    has_metric,
    avg_monthly_searches,
    competition,
    competition_index,
    low_bid,
    high_bid,
    bid_currency,
    metric_source,
    metric_date,
    source_review_status,
    source_validation_status,
    cleanup_pipeline_status,
    source_bank_bucket,
    source_page_type,
    source_role,
    source_role_label,
    proposed_bank_bucket,
    proposed_review_status,
    block_flags,
    dry_run_action,
        CASE
            WHEN exists_in_bank THEN 'Already exists in canonical seo_keyword_bank_v1; no insert.'::text
            WHEN (jsonb_array_length(block_flags) > 0) THEN ('Excluded by block flags: '::text || (block_flags)::text)
            WHEN (source_row_type = 'google_ads_related_idea'::text) THEN 'Google Ads related idea; keep on hold for manual review before any bank promotion.'::text
            WHEN (NOT has_usable_metric) THEN 'No usable metric: UNKNOWN/null metric is not eligible for promotion.'::text
            WHEN (proposed_bank_bucket = 'hold'::text) THEN 'Could not classify into safe keyword bank bucket; manual review required.'::text
            WHEN ((COALESCE(avg_monthly_searches, 0) = 0) AND ((competition IS NULL) OR (upper(competition) = 'UNKNOWN'::text))) THEN 'Zero/empty metric; manual review required.'::text
            WHEN ((bid_currency IS NOT NULL) AND (bid_currency <> 'USD'::text)) THEN (('Clean candidate with usable metric. bid_currency='::text || bid_currency) || ', do_not_copy_bid_to_bank_without_currency_logic.'::text)
            ELSE 'Clean candidate with usable metric; can be considered for future guarded promotion.'::text
        END AS reason,
    source_clusters,
    source_files,
    source_reason,
    source_notes,
    (raw_json || jsonb_build_object('source_batch', source_batch, 'source_row_type', source_row_type, 'bid_currency', bid_currency, 'has_usable_metric', has_usable_metric, 'is_no_metric_unknown', is_no_metric_unknown, 'bank_review_status', bank_review_status, 'bank_bucket', bank_bucket, 'classification_flags', jsonb_build_object('has_component', has_component, 'has_material_color', has_material_color, 'is_faq_intent', is_faq_intent, 'is_commercial_intent', is_commercial_intent, 'has_event_style', has_event_style))) AS raw_json
   FROM actioned;

create or replace view public.feya_commerce_v_seo_keyword_master_to_bank_insert_dry_run_v1 as
 WITH latest_metrics_ranked AS (
         SELECT regexp_replace(lower(btrim(COALESCE(feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS keyword_norm,
            feya_commerce_seo_keyword_metric_snapshots_v1.source_api,
            feya_commerce_seo_keyword_metric_snapshots_v1.geo,
            feya_commerce_seo_keyword_metric_snapshots_v1.language,
            feya_commerce_seo_keyword_metric_snapshots_v1.avg_monthly_searches,
            feya_commerce_seo_keyword_metric_snapshots_v1.competition,
            feya_commerce_seo_keyword_metric_snapshots_v1.competition_index,
            feya_commerce_seo_keyword_metric_snapshots_v1.low_top_of_page_bid,
            feya_commerce_seo_keyword_metric_snapshots_v1.high_top_of_page_bid,
            feya_commerce_seo_keyword_metric_snapshots_v1.fetched_at,
            feya_commerce_seo_keyword_metric_snapshots_v1.data_freshness_status,
            feya_commerce_seo_keyword_metric_snapshots_v1.raw_payload_json,
            row_number() OVER (PARTITION BY (regexp_replace(lower(btrim(COALESCE(feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm, ''::text))), '\s+'::text, ' '::text, 'g'::text)) ORDER BY feya_commerce_seo_keyword_metric_snapshots_v1.fetched_at DESC NULLS LAST, feya_commerce_seo_keyword_metric_snapshots_v1.snapshot_id DESC) AS rn
           FROM (SELECT "snapshot_id", "keyword_norm", "source_api", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_json", "fetched_at", "raw_payload_json", "data_freshness_status", "created_at", "metric_batch_id", "metric_batch_keyword_id", "keyword_id", "source_request_id", "api_version", "ingestion_run_id", "targeting_context_hash", "access_model", "bid_currency_code" FROM public.feya_commerce_seo_keyword_metric_snapshots_v1 WHERE demand_observation_key IS NULL) AS feya_commerce_seo_keyword_metric_snapshots_v1
          WHERE (NULLIF(regexp_replace(lower(btrim(COALESCE(feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL)
        ), latest_metrics AS (
         SELECT latest_metrics_ranked.keyword_norm,
            latest_metrics_ranked.source_api,
            latest_metrics_ranked.geo,
            latest_metrics_ranked.language,
            latest_metrics_ranked.avg_monthly_searches,
            latest_metrics_ranked.competition,
            latest_metrics_ranked.competition_index,
            latest_metrics_ranked.low_top_of_page_bid,
            latest_metrics_ranked.high_top_of_page_bid,
            latest_metrics_ranked.fetched_at,
            latest_metrics_ranked.data_freshness_status,
            latest_metrics_ranked.raw_payload_json,
            latest_metrics_ranked.rn
           FROM latest_metrics_ranked
          WHERE (latest_metrics_ranked.rn = 1)
        ), latest_cleanup_ranked AS (
         SELECT regexp_replace(lower(btrim(COALESCE(feya_commerce_seo_keyword_ai_cleanup_v1.keyword_norm, feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword_norm, feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.suggested_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.cleaned_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.original_keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS keyword_norm,
            feya_commerce_seo_keyword_ai_cleanup_v1.cleanup_id,
            feya_commerce_seo_keyword_ai_cleanup_v1.run_id,
            feya_commerce_seo_keyword_ai_cleanup_v1.original_keyword,
            feya_commerce_seo_keyword_ai_cleanup_v1.cleaned_keyword,
            feya_commerce_seo_keyword_ai_cleanup_v1.suggested_keyword,
            feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword,
            feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword_norm,
            feya_commerce_seo_keyword_ai_cleanup_v1.keyword_axis,
            feya_commerce_seo_keyword_ai_cleanup_v1.keyword_pattern,
            feya_commerce_seo_keyword_ai_cleanup_v1.suggested_page_level,
            feya_commerce_seo_keyword_ai_cleanup_v1.ai_intent,
            feya_commerce_seo_keyword_ai_cleanup_v1.ai_rewrite_status,
            feya_commerce_seo_keyword_ai_cleanup_v1.should_validate_api,
            feya_commerce_seo_keyword_ai_cleanup_v1.should_use_for_product,
            feya_commerce_seo_keyword_ai_cleanup_v1.should_use_for_collection,
            feya_commerce_seo_keyword_ai_cleanup_v1.should_use_for_image_alt,
            feya_commerce_seo_keyword_ai_cleanup_v1.should_hold,
            feya_commerce_seo_keyword_ai_cleanup_v1.warning_flags,
            feya_commerce_seo_keyword_ai_cleanup_v1.ai_reason,
            feya_commerce_seo_keyword_ai_cleanup_v1.review_status,
            feya_commerce_seo_keyword_ai_cleanup_v1.created_at,
            feya_commerce_seo_keyword_ai_cleanup_v1.updated_at,
            row_number() OVER (PARTITION BY (regexp_replace(lower(btrim(COALESCE(feya_commerce_seo_keyword_ai_cleanup_v1.keyword_norm, feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword_norm, feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.suggested_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.cleaned_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.original_keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text)) ORDER BY feya_commerce_seo_keyword_ai_cleanup_v1.created_at DESC NULLS LAST, feya_commerce_seo_keyword_ai_cleanup_v1.cleanup_id DESC) AS rn
           FROM feya_commerce_seo_keyword_ai_cleanup_v1
          WHERE (NULLIF(regexp_replace(lower(btrim(COALESCE(feya_commerce_seo_keyword_ai_cleanup_v1.keyword_norm, feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword_norm, feya_commerce_seo_keyword_ai_cleanup_v1.approved_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.suggested_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.cleaned_keyword, feya_commerce_seo_keyword_ai_cleanup_v1.original_keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL)
        ), latest_cleanup AS (
         SELECT latest_cleanup_ranked.keyword_norm,
            latest_cleanup_ranked.cleanup_id,
            latest_cleanup_ranked.run_id,
            latest_cleanup_ranked.original_keyword,
            latest_cleanup_ranked.cleaned_keyword,
            latest_cleanup_ranked.suggested_keyword,
            latest_cleanup_ranked.approved_keyword,
            latest_cleanup_ranked.approved_keyword_norm,
            latest_cleanup_ranked.keyword_axis,
            latest_cleanup_ranked.keyword_pattern,
            latest_cleanup_ranked.suggested_page_level,
            latest_cleanup_ranked.ai_intent,
            latest_cleanup_ranked.ai_rewrite_status,
            latest_cleanup_ranked.should_validate_api,
            latest_cleanup_ranked.should_use_for_product,
            latest_cleanup_ranked.should_use_for_collection,
            latest_cleanup_ranked.should_use_for_image_alt,
            latest_cleanup_ranked.should_hold,
            latest_cleanup_ranked.warning_flags,
            latest_cleanup_ranked.ai_reason,
            latest_cleanup_ranked.review_status,
            latest_cleanup_ranked.created_at,
            latest_cleanup_ranked.updated_at,
            latest_cleanup_ranked.rn
           FROM latest_cleanup_ranked
          WHERE (latest_cleanup_ranked.rn = 1)
        ), bank_best_ranked AS (
         SELECT b.id,
            b.keyword,
            b.keyword_norm,
            b.bank_bucket,
            b.review_status,
            b.source_clusters,
            b.score,
            b.avg_monthly_searches,
            b.competition,
            b.competition_index,
            b.low_bid,
            b.high_bid,
            b.region,
            b.language,
            b.metric_source,
            b.page_type,
            b.role,
            b.role_label,
            b.last_checked,
            b.duplicate_count,
            b.reason,
            b.notes,
            b.source_files,
            b.created_at,
            b.updated_at,
            row_number() OVER (PARTITION BY b.keyword_norm ORDER BY
                CASE b.review_status
                    WHEN 'approved_draft'::text THEN 1
                    WHEN 'hold'::text THEN 2
                    WHEN 'reject'::text THEN 3
                    ELSE 4
                END, b.score DESC NULLS LAST, b.avg_monthly_searches DESC NULLS LAST, b.updated_at DESC NULLS LAST, b.keyword) AS rn
           FROM seo_keyword_bank_v1 b
        ), bank_best AS (
         SELECT bank_best_ranked.id,
            bank_best_ranked.keyword,
            bank_best_ranked.keyword_norm,
            bank_best_ranked.bank_bucket,
            bank_best_ranked.review_status,
            bank_best_ranked.source_clusters,
            bank_best_ranked.score,
            bank_best_ranked.avg_monthly_searches,
            bank_best_ranked.competition,
            bank_best_ranked.competition_index,
            bank_best_ranked.low_bid,
            bank_best_ranked.high_bid,
            bank_best_ranked.region,
            bank_best_ranked.language,
            bank_best_ranked.metric_source,
            bank_best_ranked.page_type,
            bank_best_ranked.role,
            bank_best_ranked.role_label,
            bank_best_ranked.last_checked,
            bank_best_ranked.duplicate_count,
            bank_best_ranked.reason,
            bank_best_ranked.notes,
            bank_best_ranked.source_files,
            bank_best_ranked.created_at,
            bank_best_ranked.updated_at,
            bank_best_ranked.rn
           FROM bank_best_ranked
          WHERE (bank_best_ranked.rn = 1)
        ), listing_master_norms AS (
         SELECT DISTINCT vw_seo_keyword_bank_v1_for_listing_master.keyword_norm
           FROM vw_seo_keyword_bank_v1_for_listing_master
        ), source_candidates AS (
         SELECT 'feya_commerce_seo_keyword_master_v1'::text AS candidate_source,
            1 AS source_priority,
            m.keyword AS source_keyword,
            regexp_replace(lower(btrim(COALESCE(m.keyword_norm, m.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS source_keyword_norm,
            NULL::integer AS source_avg_monthly_searches,
            NULL::text AS source_competition,
            NULL::numeric AS source_competition_index,
            NULL::numeric AS source_low_bid,
            NULL::numeric AS source_high_bid,
            NULL::text AS source_metric_source,
            NULL::timestamp with time zone AS source_metric_date,
            c.review_status AS source_review_status,
            m.validation_status AS source_validation_status,
            concat_ws(' / '::text, c.review_status, c.ai_rewrite_status, c.ai_intent,
                CASE
                    WHEN c.should_hold THEN 'should_hold'::text
                    ELSE NULL::text
                END) AS cleanup_pipeline_status,
            m.suggested_page_level AS source_bank_bucket,
            m.suggested_page_level AS source_page_type,
            m.priority_tier AS source_role,
            m.validation_priority AS source_role_label,
            concat_ws(', '::text, m.keyword_axis, m.keyword_pattern) AS source_clusters,
            m.source AS source_files,
            m.reason AS source_reason,
            NULL::text AS source_notes,
            jsonb_build_object('source_table', 'feya_commerce_seo_keyword_master_v1', 'keyword_id', m.keyword_id, 'keyword_axis', m.keyword_axis, 'keyword_pattern', m.keyword_pattern, 'suggested_page_level', m.suggested_page_level, 'priority_tier', m.priority_tier, 'validation_priority', m.validation_priority, 'validation_status', m.validation_status, 'requires_api_validation', m.requires_api_validation, 'product_count', m.product_count, 'sample_products', m.sample_products, 'cleanup_id', c.cleanup_id, 'cleanup_review_status', c.review_status, 'ai_rewrite_status', c.ai_rewrite_status, 'ai_intent', c.ai_intent, 'warning_flags', c.warning_flags, 'ai_reason', c.ai_reason) AS source_raw_json
           FROM (feya_commerce_seo_keyword_master_v1 m
             LEFT JOIN latest_cleanup c ON ((c.keyword_norm = regexp_replace(lower(btrim(COALESCE(m.keyword_norm, m.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text))))
          WHERE ((m.active_flag IS TRUE) AND (NULLIF(regexp_replace(lower(btrim(COALESCE(m.keyword_norm, m.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL))
        UNION ALL
         SELECT 'feya_commerce_v_seo_keyword_recommendation_v1'::text AS candidate_source,
            2 AS source_priority,
            r.keyword AS source_keyword,
            regexp_replace(lower(btrim(COALESCE(r.keyword_norm, r.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS source_keyword_norm,
            r.avg_monthly_searches AS source_avg_monthly_searches,
            r.competition AS source_competition,
            r.competition_index AS source_competition_index,
            r.low_top_of_page_bid AS source_low_bid,
            r.high_top_of_page_bid AS source_high_bid,
                CASE
                    WHEN (r.metric_validation_status = 'has_fresh_metrics'::text) THEN 'feya_commerce_v_seo_keyword_recommendation_v1'::text
                    ELSE NULL::text
                END AS source_metric_source,
            r.latest_metric_fetched_at AS source_metric_date,
            r.review_status AS source_review_status,
            r.metric_validation_status AS source_validation_status,
            concat_ws(' / '::text, r.review_status, r.metric_validation_status, r.recommendation_status) AS cleanup_pipeline_status,
            r.suggested_page_level AS source_bank_bucket,
            r.suggested_page_level AS source_page_type,
            r.recommendation_status AS source_role,
            (r.recommendation_score)::text AS source_role_label,
            concat_ws(', '::text, r.keyword_axis, r.keyword_pattern) AS source_clusters,
            'feya_commerce_v_seo_keyword_recommendation_v1'::text AS source_files,
            r.ai_reason AS source_reason,
            NULL::text AS source_notes,
            jsonb_build_object('source_view', 'feya_commerce_v_seo_keyword_recommendation_v1', 'keyword_id', r.keyword_id, 'keyword_axis', r.keyword_axis, 'keyword_pattern', r.keyword_pattern, 'suggested_page_level', r.suggested_page_level, 'should_use_for_product', r.should_use_for_product, 'should_use_for_collection', r.should_use_for_collection, 'should_use_for_image_alt', r.should_use_for_image_alt, 'should_hold', r.should_hold, 'review_status', r.review_status, 'metric_validation_status', r.metric_validation_status, 'recommendation_status', r.recommendation_status, 'recommendation_score', r.recommendation_score, 'warning_flags', r.warning_flags, 'ai_reason', r.ai_reason) AS source_raw_json
           FROM feya_commerce_v_seo_keyword_recommendation_v1 r
          WHERE (NULLIF(regexp_replace(lower(btrim(COALESCE(r.keyword_norm, r.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL)
        UNION ALL
         SELECT 'feya_commerce_seo_keyword_metric_snapshots_v1'::text AS candidate_source,
            3 AS source_priority,
            lm.keyword_norm AS source_keyword,
            lm.keyword_norm AS source_keyword_norm,
            lm.avg_monthly_searches AS source_avg_monthly_searches,
            lm.competition AS source_competition,
            lm.competition_index AS source_competition_index,
            lm.low_top_of_page_bid AS source_low_bid,
            lm.high_top_of_page_bid AS source_high_bid,
            lm.source_api AS source_metric_source,
            lm.fetched_at AS source_metric_date,
            lm.data_freshness_status AS source_review_status,
            lm.data_freshness_status AS source_validation_status,
            lm.data_freshness_status AS cleanup_pipeline_status,
            NULL::text AS source_bank_bucket,
            NULL::text AS source_page_type,
            NULL::text AS source_role,
            NULL::text AS source_role_label,
            NULL::text AS source_clusters,
            'feya_commerce_seo_keyword_metric_snapshots_v1'::text AS source_files,
            lm.data_freshness_status AS source_reason,
            NULL::text AS source_notes,
            jsonb_build_object('source_table', 'feya_commerce_seo_keyword_metric_snapshots_v1', 'source_api', lm.source_api, 'geo', lm.geo, 'language', lm.language, 'data_freshness_status', lm.data_freshness_status, 'raw_payload_json', lm.raw_payload_json) AS source_raw_json
           FROM latest_metrics lm
        ), normalized_candidates AS (
         SELECT sc.candidate_source,
            sc.source_priority,
            sc.source_keyword,
            sc.source_keyword_norm,
            sc.source_avg_monthly_searches,
            sc.source_competition,
            sc.source_competition_index,
            sc.source_low_bid,
            sc.source_high_bid,
            sc.source_metric_source,
            sc.source_metric_date,
            sc.source_review_status,
            sc.source_validation_status,
            sc.cleanup_pipeline_status,
            sc.source_bank_bucket,
            sc.source_page_type,
            sc.source_role,
            sc.source_role_label,
            sc.source_clusters,
            sc.source_files,
            sc.source_reason,
            sc.source_notes,
            sc.source_raw_json,
            NULLIF(btrim(sc.source_keyword), ''::text) AS candidate_keyword,
            regexp_replace(lower(btrim(COALESCE(sc.source_keyword_norm, sc.source_keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS candidate_keyword_norm
           FROM source_candidates sc
        ), deduped_candidates AS (
         SELECT x.candidate_source,
            x.source_priority,
            x.source_keyword,
            x.source_keyword_norm,
            x.source_avg_monthly_searches,
            x.source_competition,
            x.source_competition_index,
            x.source_low_bid,
            x.source_high_bid,
            x.source_metric_source,
            x.source_metric_date,
            x.source_review_status,
            x.source_validation_status,
            x.cleanup_pipeline_status,
            x.source_bank_bucket,
            x.source_page_type,
            x.source_role,
            x.source_role_label,
            x.source_clusters,
            x.source_files,
            x.source_reason,
            x.source_notes,
            x.source_raw_json,
            x.candidate_keyword,
            x.candidate_keyword_norm,
            x.rn
           FROM ( SELECT nc.candidate_source,
                    nc.source_priority,
                    nc.source_keyword,
                    nc.source_keyword_norm,
                    nc.source_avg_monthly_searches,
                    nc.source_competition,
                    nc.source_competition_index,
                    nc.source_low_bid,
                    nc.source_high_bid,
                    nc.source_metric_source,
                    nc.source_metric_date,
                    nc.source_review_status,
                    nc.source_validation_status,
                    nc.cleanup_pipeline_status,
                    nc.source_bank_bucket,
                    nc.source_page_type,
                    nc.source_role,
                    nc.source_role_label,
                    nc.source_clusters,
                    nc.source_files,
                    nc.source_reason,
                    nc.source_notes,
                    nc.source_raw_json,
                    nc.candidate_keyword,
                    nc.candidate_keyword_norm,
                    row_number() OVER (PARTITION BY nc.candidate_keyword_norm ORDER BY nc.source_priority, nc.source_metric_date DESC NULLS LAST, nc.candidate_keyword) AS rn
                   FROM normalized_candidates nc
                  WHERE (NULLIF(nc.candidate_keyword_norm, ''::text) IS NOT NULL)) x
          WHERE (x.rn = 1)
        ), enriched AS (
         SELECT d.candidate_keyword,
            d.candidate_keyword_norm,
            d.candidate_source,
            (b.keyword_norm IS NOT NULL) AS exists_in_bank,
            (lmv.keyword_norm IS NOT NULL) AS exists_in_listing_master,
            COALESCE(mt.avg_monthly_searches, d.source_avg_monthly_searches) AS avg_monthly_searches,
            COALESCE(mt.competition, d.source_competition) AS competition,
            COALESCE(mt.competition_index, d.source_competition_index) AS competition_index,
            COALESCE(mt.low_top_of_page_bid, d.source_low_bid) AS low_bid,
            COALESCE(mt.high_top_of_page_bid, d.source_high_bid) AS high_bid,
            COALESCE(mt.source_api, d.source_metric_source) AS metric_source,
            COALESCE(mt.fetched_at, d.source_metric_date) AS metric_date,
            COALESCE(d.source_review_status, b.review_status) AS source_review_status,
            d.source_validation_status,
            d.cleanup_pipeline_status,
            COALESCE(b.bank_bucket, d.source_bank_bucket) AS source_bank_bucket,
            COALESCE(b.page_type, d.source_page_type) AS source_page_type,
            COALESCE(b.role, d.source_role) AS source_role,
            COALESCE(b.role_label, d.source_role_label) AS source_role_label,
            COALESCE(b.source_clusters, d.source_clusters) AS source_clusters,
            COALESCE(b.source_files, d.source_files) AS source_files,
            COALESCE(b.reason, d.source_reason) AS source_reason,
            COALESCE(b.notes, d.source_notes) AS source_notes,
            b.review_status AS bank_review_status,
            b.bank_bucket,
            d.source_raw_json,
            lower(d.candidate_keyword_norm) AS match_text
           FROM (((deduped_candidates d
             LEFT JOIN latest_metrics mt ON ((mt.keyword_norm = d.candidate_keyword_norm)))
             LEFT JOIN bank_best b ON ((b.keyword_norm = d.candidate_keyword_norm)))
             LEFT JOIN listing_master_norms lmv ON ((lmv.keyword_norm = d.candidate_keyword_norm)))
        ), flags AS (
         SELECT e.candidate_keyword,
            e.candidate_keyword_norm,
            e.candidate_source,
            e.exists_in_bank,
            e.exists_in_listing_master,
            e.avg_monthly_searches,
            e.competition,
            e.competition_index,
            e.low_bid,
            e.high_bid,
            e.metric_source,
            e.metric_date,
            e.source_review_status,
            e.source_validation_status,
            e.cleanup_pipeline_status,
            e.source_bank_bucket,
            e.source_page_type,
            e.source_role,
            e.source_role_label,
            e.source_clusters,
            e.source_files,
            e.source_reason,
            e.source_notes,
            e.bank_review_status,
            e.bank_bucket,
            e.source_raw_json,
            e.match_text,
            ((e.avg_monthly_searches IS NOT NULL) OR (e.competition IS NOT NULL) OR (e.competition_index IS NOT NULL) OR (e.low_bid IS NOT NULL) OR (e.high_bid IS NOT NULL) OR (e.metric_source IS NOT NULL)) AS has_metric,
            ((e.avg_monthly_searches IS NOT NULL) OR (e.competition IS NOT NULL) OR (e.competition_index IS NOT NULL) OR (e.low_bid IS NOT NULL) OR (e.high_bid IS NOT NULL)) AS has_real_metric_signal,
            ((e.match_text ~~ '%armor%'::text) OR (e.match_text ~~ '%armour%'::text) OR (e.match_text ~~ '%shoulder%'::text) OR (e.match_text ~~ '%shoulders%'::text) OR (e.match_text ~~ '%bracer%'::text) OR (e.match_text ~~ '%arm cuff%'::text) OR (e.match_text ~~ '%choker%'::text) OR (e.match_text ~~ '%collar%'::text) OR (e.match_text ~~ '%harness%'::text) OR (e.match_text ~~ '%bodysuit%'::text) OR (e.match_text ~~ '%body suit%'::text) OR (e.match_text ~~ '%mask%'::text) OR (e.match_text ~~ '%headpiece%'::text) OR (e.match_text ~~ '%head piece%'::text) OR (e.match_text ~~ '%horn%'::text) OR (e.match_text ~~ '%corset%'::text) OR (e.match_text ~~ '%skirt%'::text) OR (e.match_text ~~ '%dress%'::text) OR (e.match_text ~~ '%belt%'::text) OR (e.match_text ~~ '%chain%'::text) OR (e.match_text ~~ '%wings%'::text)) AS has_component,
            ((e.match_text ~~ '%gold%'::text) OR (e.match_text ~~ '%silver%'::text) OR (e.match_text ~~ '%mirror%'::text) OR (e.match_text ~~ '%metallic%'::text) OR (e.match_text ~~ '%reflective%'::text) OR (e.match_text ~~ '%holographic%'::text) OR (e.match_text ~~ '%chrome%'::text) OR (e.match_text ~~ '%leather%'::text) OR (e.match_text ~~ '%acrylic%'::text) OR (e.match_text ~~ '%black%'::text) OR (e.match_text ~~ '%white%'::text) OR (e.match_text ~~ '%iridescent%'::text) OR (e.match_text ~~ '%shiny%'::text)) AS has_material_color,
            ((e.match_text ~~ '%rave%'::text) OR (e.match_text ~~ '%edm%'::text) OR (e.match_text ~~ '%festival%'::text) OR (e.match_text ~~ '%burning man%'::text) OR (e.match_text ~~ '%coachella%'::text) OR (e.match_text ~~ '%stage%'::text) OR (e.match_text ~~ '%performance%'::text) OR (e.match_text ~~ '%drag%'::text) OR (e.match_text ~~ '%clubwear%'::text) OR (e.match_text ~~ '%dancer%'::text) OR (e.match_text ~~ '%dance%'::text) OR (e.match_text ~~ '%futuristic%'::text) OR (e.match_text ~~ '%cyberpunk%'::text) OR (e.match_text ~~ '%apocalyptic%'::text) OR (e.match_text ~~ '%post apocalyptic%'::text) OR (e.match_text ~~ '%desert%'::text) OR (e.match_text ~~ '%cosmic%'::text) OR (e.match_text ~~ '%sci fi%'::text) OR (e.match_text ~~ '%sci-fi%'::text) OR (e.match_text ~~ '%punk%'::text) OR (e.match_text ~~ '%glam%'::text)) AS has_event_style,
            ((e.match_text ~~ '%outfit%'::text) OR (e.match_text ~~ '%costume%'::text) OR (e.match_text ~~ '%dress%'::text) OR (e.match_text ~~ '% set%'::text)) AS has_visual_product_word,
            ((e.match_text ~~ '%price%'::text) OR (e.match_text ~~ '%cost%'::text) OR (e.match_text ~~ '%shipping%'::text) OR (e.match_text ~~ '%delivery%'::text) OR (e.match_text ~~ '%size%'::text) OR (e.match_text ~~ '%sizing%'::text) OR (e.match_text ~~ '%how to%'::text) OR (e.match_text ~~ '%what to wear%'::text)) AS is_faq_intent,
            ((e.match_text ~~ '%buy%'::text) OR (e.match_text ~~ '%shop%'::text) OR (e.match_text ~~ '%order%'::text) OR (e.match_text ~~ '%custom%'::text) OR (e.match_text ~~ '%handmade%'::text) OR (e.match_text ~~ '%for sale%'::text) OR (e.match_text ~~ '%online%'::text) OR (e.match_text ~~ '%website%'::text) OR (e.match_text ~~ '%store%'::text)) AS is_commercial_intent,
            to_jsonb(array_remove(ARRAY[
                CASE
                    WHEN ((e.match_text ~~ '%lego%'::text) OR (e.match_text ~~ '%pokemon%'::text) OR (e.match_text ~~ '%pokémon%'::text) OR (e.match_text ~~ '%barbie%'::text) OR (e.match_text ~~ '%disney%'::text) OR (e.match_text ~~ '%wonder woman%'::text) OR (e.match_text ~~ '%batman%'::text) OR (e.match_text ~~ '%harry potter%'::text) OR (e.match_text ~~ '%star wars%'::text) OR (e.match_text ~~ '%mandalorian%'::text) OR (e.match_text ~~ '%spongebob%'::text) OR (e.match_text ~~ '%shrek%'::text) OR (e.match_text ~~ '%my little pony%'::text)) THEN 'franchise_brand'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%kids%'::text) OR (e.match_text ~~ '% child%'::text) OR (e.match_text ~~ '%children%'::text) OR (e.match_text ~~ '%baby%'::text) OR (e.match_text ~~ '%toddler%'::text) OR (e.match_text ~~ '%dog costume%'::text) OR (e.match_text ~~ '%pet costume%'::text)) THEN 'kids_pet'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%diy%'::text) OR (e.match_text ~~ '%pattern%'::text) OR (e.match_text ~~ '%template%'::text) OR (e.match_text ~~ '%sewing pattern%'::text) OR (e.match_text ~~ '%make your own%'::text)) THEN 'diy_pattern'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%bridal%'::text) OR (e.match_text ~~ '%bride%'::text) OR (e.match_text ~~ '%wedding%'::text) OR (e.match_text ~~ '%bridesmaid%'::text) OR (e.match_text ~~ '%prom%'::text) OR (e.match_text ~~ '%homecoming%'::text) OR (e.match_text ~~ '%flapper%'::text) OR (e.match_text ~~ '%gatsby%'::text) OR (e.match_text ~~ '%renaissance%'::text) OR (e.match_text ~~ '%medieval%'::text)) THEN 'wrong_occasion'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%n95%'::text) OR (e.match_text ~~ '%kn95%'::text) OR (e.match_text ~~ '%surgical mask%'::text) OR (e.match_text ~~ '%medical mask%'::text) OR (e.match_text ~~ '%respirator%'::text) OR (e.match_text ~~ '%dust mask%'::text) OR (e.match_text ~~ '%gas mask%'::text) OR (e.match_text ~~ '%protective face mask%'::text)) THEN 'medical_safety'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%fall protection%'::text) OR (e.match_text ~~ '%safety harness%'::text) OR (e.match_text ~~ '%climbing harness%'::text) OR (e.match_text ~~ '%wire harness%'::text) OR (e.match_text ~~ '%wiring harness%'::text) OR (e.match_text ~~ '%osha%'::text) OR (e.match_text ~~ '%ansi%'::text) OR (e.match_text ~~ '%lanyard%'::text)) THEN 'industrial_harness'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((e.match_text ~~ '%necklace%'::text) OR (e.match_text ~~ '%earrings%'::text) OR (e.match_text ~~ '%diamond%'::text) OR (e.match_text ~~ '%pearl jewelry%'::text)) THEN 'jewelry_only'::text
                    ELSE NULL::text
                END], NULL::text)) AS block_flags
           FROM enriched e
        ), bucketed AS (
         SELECT f.candidate_keyword,
            f.candidate_keyword_norm,
            f.candidate_source,
            f.exists_in_bank,
            f.exists_in_listing_master,
            f.avg_monthly_searches,
            f.competition,
            f.competition_index,
            f.low_bid,
            f.high_bid,
            f.metric_source,
            f.metric_date,
            f.source_review_status,
            f.source_validation_status,
            f.cleanup_pipeline_status,
            f.source_bank_bucket,
            f.source_page_type,
            f.source_role,
            f.source_role_label,
            f.source_clusters,
            f.source_files,
            f.source_reason,
            f.source_notes,
            f.bank_review_status,
            f.bank_bucket,
            f.source_raw_json,
            f.match_text,
            f.has_metric,
            f.has_real_metric_signal,
            f.has_component,
            f.has_material_color,
            f.has_event_style,
            f.has_visual_product_word,
            f.is_faq_intent,
            f.is_commercial_intent,
            f.block_flags,
                CASE
                    WHEN f.is_faq_intent THEN 'faq'::text
                    WHEN f.is_commercial_intent THEN 'commercial_collection'::text
                    WHEN (f.has_component AND f.has_material_color) THEN 'product_or_alt'::text
                    WHEN f.has_component THEN 'product'::text
                    WHEN (f.has_material_color AND f.has_visual_product_word) THEN 'visual_collection'::text
                    WHEN f.has_event_style THEN 'collection'::text
                    ELSE 'hold'::text
                END AS proposed_bank_bucket
           FROM flags f
        ), decided AS (
         SELECT b.candidate_keyword,
            b.candidate_keyword_norm,
            b.candidate_source,
            b.exists_in_bank,
            b.exists_in_listing_master,
            b.avg_monthly_searches,
            b.competition,
            b.competition_index,
            b.low_bid,
            b.high_bid,
            b.metric_source,
            b.metric_date,
            b.source_review_status,
            b.source_validation_status,
            b.cleanup_pipeline_status,
            b.source_bank_bucket,
            b.source_page_type,
            b.source_role,
            b.source_role_label,
            b.source_clusters,
            b.source_files,
            b.source_reason,
            b.source_notes,
            b.bank_review_status,
            b.bank_bucket,
            b.source_raw_json,
            b.match_text,
            b.has_metric,
            b.has_real_metric_signal,
            b.has_component,
            b.has_material_color,
            b.has_event_style,
            b.has_visual_product_word,
            b.is_faq_intent,
            b.is_commercial_intent,
            b.block_flags,
            b.proposed_bank_bucket,
                CASE
                    WHEN (jsonb_array_length(b.block_flags) > 0) THEN 'reject'::text
                    WHEN b.exists_in_bank THEN b.bank_review_status
                    WHEN (NOT b.has_metric) THEN 'hold'::text
                    WHEN (b.proposed_bank_bucket = 'hold'::text) THEN 'hold'::text
                    WHEN ((COALESCE(b.avg_monthly_searches, 0) = 0) AND (b.competition IS NULL)) THEN 'hold'::text
                    WHEN (NOT b.has_real_metric_signal) THEN 'hold'::text
                    ELSE 'approved_draft'::text
                END AS proposed_review_status
           FROM bucketed b
        ), actioned AS (
         SELECT d.candidate_keyword,
            d.candidate_keyword_norm,
            d.candidate_source,
            d.exists_in_bank,
            d.exists_in_listing_master,
            d.avg_monthly_searches,
            d.competition,
            d.competition_index,
            d.low_bid,
            d.high_bid,
            d.metric_source,
            d.metric_date,
            d.source_review_status,
            d.source_validation_status,
            d.cleanup_pipeline_status,
            d.source_bank_bucket,
            d.source_page_type,
            d.source_role,
            d.source_role_label,
            d.source_clusters,
            d.source_files,
            d.source_reason,
            d.source_notes,
            d.bank_review_status,
            d.bank_bucket,
            d.source_raw_json,
            d.match_text,
            d.has_metric,
            d.has_real_metric_signal,
            d.has_component,
            d.has_material_color,
            d.has_event_style,
            d.has_visual_product_word,
            d.is_faq_intent,
            d.is_commercial_intent,
            d.block_flags,
            d.proposed_bank_bucket,
            d.proposed_review_status,
                CASE
                    WHEN d.exists_in_bank THEN 'excluded_duplicate'::text
                    WHEN (jsonb_array_length(d.block_flags) > 0) THEN 'excluded_noise'::text
                    WHEN (NOT d.has_metric) THEN 'needs_manual_review_no_metric'::text
                    WHEN (d.proposed_bank_bucket = 'hold'::text) THEN 'needs_manual_review_bucket'::text
                    WHEN (((d.avg_monthly_searches IS NULL) AND (d.competition IS NULL) AND (d.competition_index IS NULL) AND (d.low_bid IS NULL) AND (d.high_bid IS NULL)) OR ((COALESCE(d.avg_monthly_searches, 0) = 0) AND (d.competition IS NULL))) THEN 'needs_manual_review_zero_metric'::text
                    WHEN (d.proposed_review_status = 'approved_draft'::text) THEN 'would_insert'::text
                    ELSE 'needs_manual_review_bucket'::text
                END AS dry_run_action
           FROM decided d
        )
 SELECT candidate_keyword,
    candidate_keyword_norm,
    candidate_source,
    exists_in_bank,
    exists_in_listing_master,
    has_metric,
    avg_monthly_searches,
    competition,
    competition_index,
    low_bid,
    high_bid,
    metric_source,
    metric_date,
    source_review_status,
    source_validation_status,
    cleanup_pipeline_status,
    source_bank_bucket,
    source_page_type,
    source_role,
    source_role_label,
    proposed_bank_bucket,
    proposed_review_status,
    block_flags,
    dry_run_action,
        CASE
            WHEN (dry_run_action = 'excluded_duplicate'::text) THEN 'Уже есть в canonical seo_keyword_bank_v1; не вставлять повторно.'::text
            WHEN (dry_run_action = 'excluded_noise'::text) THEN ('Исключено rule-based block flags: '::text || (block_flags)::text)
            WHEN (dry_run_action = 'needs_manual_review_no_metric'::text) THEN 'Нет метрик и нет metric source; сначала отправить на Google Ads / ручную проверку.'::text
            WHEN (dry_run_action = 'needs_manual_review_bucket'::text) THEN 'Не удалось уверенно определить валидный bucket; нужен ручной review.'::text
            WHEN (dry_run_action = 'needs_manual_review_zero_metric'::text) THEN 'Метрика пустая или нулевая; не auto-approve.'::text
            WHEN (dry_run_action = 'would_insert'::text) THEN 'Чистый кандидат: не дубликат, без block flags, есть метрики, bucket валиден; можно готовить guarded insert.'::text
            ELSE 'Нужен ручной review.'::text
        END AS reason,
    source_clusters,
    source_files,
    source_reason,
    source_notes,
    (source_raw_json || jsonb_build_object('exists_in_bank', exists_in_bank, 'exists_in_listing_master', exists_in_listing_master, 'has_metric', has_metric, 'has_real_metric_signal', has_real_metric_signal, 'bank_review_status', bank_review_status, 'bank_bucket', bank_bucket, 'classification_flags', jsonb_build_object('has_component', has_component, 'has_material_color', has_material_color, 'has_event_style', has_event_style, 'is_faq_intent', is_faq_intent, 'is_commercial_intent', is_commercial_intent, 'has_visual_product_word', has_visual_product_word))) AS raw_json
   FROM actioned;

create or replace view public.feya_commerce_v_seo_keyword_metric_import_ready_v1 as
 SELECT s.import_row_id,
    s.batch_code,
    COALESCE(s.keyword, m.keyword) AS keyword,
    regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS keyword_norm,
    s.geo,
    s.language,
    s.avg_monthly_searches,
        CASE
            WHEN (s.competition IS NULL) THEN NULL::text
            WHEN (lower(s.competition) = 'низкая'::text) THEN 'LOW'::text
            WHEN (lower(s.competition) = 'средняя'::text) THEN 'MEDIUM'::text
            WHEN (lower(s.competition) = 'высокая'::text) THEN 'HIGH'::text
            ELSE upper(s.competition)
        END AS competition,
    s.competition_index,
    s.low_top_of_page_bid,
    s.high_top_of_page_bid,
    s.monthly_search_volumes_raw,
    s.source_file_name,
    s.imported_at,
    s.import_status,
    s.import_note
   FROM (((SELECT "import_row_id", "batch_code", "keyword", "keyword_norm", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_raw", "source_file_name", "imported_at", "import_status", "import_note", "created_at" FROM public.feya_commerce_seo_keyword_metric_import_staging_v1 WHERE demand_observation_key IS NULL) AS s
     JOIN feya_commerce_seo_keyword_master_v1 m ON (((m.keyword_norm = regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text)) AND (m.active_flag IS TRUE))))
     JOIN feya_commerce_v_seo_keyword_validation_export_us_en_v1 e ON (((e.keyword_norm = m.keyword_norm) AND (e.batch_code = s.batch_code) AND (e.geo = s.geo) AND (e.language = s.language))))
  WHERE ((NULLIF(regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL) AND (NOT ((s.avg_monthly_searches IS NULL) AND (s.competition IS NULL) AND (s.competition_index IS NULL))) AND ((s.avg_monthly_searches IS NULL) OR (s.avg_monthly_searches >= 0)) AND ((s.competition IS NULL) OR (lower(s.competition) = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'unknown'::text, 'низкая'::text, 'средняя'::text, 'высокая'::text]))));

create or replace view public.feya_commerce_v_seo_keyword_metric_import_validation_report_v1 as
 WITH staging AS (
         SELECT s.import_row_id,
            s.batch_code,
            s.keyword,
            s.keyword_norm,
            s.geo,
            s.language,
            s.avg_monthly_searches,
            s.competition,
            s.competition_index,
            s.low_top_of_page_bid,
            s.high_top_of_page_bid,
            s.monthly_search_volumes_raw,
            s.source_file_name,
            s.imported_at,
            s.import_status,
            s.import_note,
            s.created_at,
            regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS keyword_norm_clean,
            m.keyword_id,
            m.keyword AS master_keyword,
            m.validation_status AS master_validation_status,
            m.priority_tier AS master_priority_tier,
            m.validation_priority AS master_validation_priority,
            e.keyword_norm AS export_keyword_norm
           FROM (((SELECT "import_row_id", "batch_code", "keyword", "keyword_norm", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_raw", "source_file_name", "imported_at", "import_status", "import_note", "created_at" FROM public.feya_commerce_seo_keyword_metric_import_staging_v1 WHERE demand_observation_key IS NULL) AS s
             LEFT JOIN feya_commerce_seo_keyword_master_v1 m ON (((m.keyword_norm = regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text)) AND (m.active_flag IS TRUE))))
             LEFT JOIN feya_commerce_v_seo_keyword_validation_export_us_en_v1 e ON (((e.keyword_norm = regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text)) AND (e.batch_code = s.batch_code) AND (e.geo = s.geo) AND (e.language = s.language))))
        ), row_checks AS (
         SELECT staging.import_row_id,
            staging.batch_code,
            staging.keyword,
            staging.keyword_norm,
            staging.geo,
            staging.language,
            staging.avg_monthly_searches,
            staging.competition,
            staging.competition_index,
            staging.low_top_of_page_bid,
            staging.high_top_of_page_bid,
            staging.monthly_search_volumes_raw,
            staging.source_file_name,
            staging.imported_at,
            staging.import_status,
            staging.import_note,
            staging.created_at,
            staging.keyword_norm_clean,
            staging.keyword_id,
            staging.master_keyword,
            staging.master_validation_status,
            staging.master_priority_tier,
            staging.master_validation_priority,
            staging.export_keyword_norm,
                CASE
                    WHEN (NULLIF(staging.keyword_norm_clean, ''::text) IS NULL) THEN 'invalid_empty_keyword_norm'::text
                    WHEN (staging.keyword_id IS NULL) THEN 'not_matched_to_keyword_master'::text
                    WHEN (staging.export_keyword_norm IS NULL) THEN 'not_in_expected_export_batch'::text
                    WHEN ((staging.avg_monthly_searches IS NULL) AND (staging.competition IS NULL) AND (staging.competition_index IS NULL)) THEN 'missing_metrics'::text
                    WHEN ((staging.competition IS NOT NULL) AND (lower(staging.competition) <> ALL (ARRAY['low'::text, 'medium'::text, 'high'::text, 'unknown'::text, 'низкая'::text, 'средняя'::text, 'высокая'::text]))) THEN 'competition_value_needs_review'::text
                    WHEN ((staging.avg_monthly_searches IS NOT NULL) AND (staging.avg_monthly_searches < 0)) THEN 'negative_volume_invalid'::text
                    ELSE 'ready_for_snapshot'::text
                END AS validation_result,
                CASE
                    WHEN (staging.keyword_id IS NULL) THEN true
                    WHEN (staging.export_keyword_norm IS NULL) THEN true
                    WHEN ((staging.avg_monthly_searches IS NULL) AND (staging.competition IS NULL) AND (staging.competition_index IS NULL)) THEN true
                    WHEN ((staging.competition IS NOT NULL) AND (lower(staging.competition) <> ALL (ARRAY['low'::text, 'medium'::text, 'high'::text, 'unknown'::text, 'низкая'::text, 'средняя'::text, 'высокая'::text]))) THEN true
                    WHEN ((staging.avg_monthly_searches IS NOT NULL) AND (staging.avg_monthly_searches < 0)) THEN true
                    ELSE false
                END AS needs_manual_review
           FROM staging
        ), summary AS (
         SELECT 'summary'::text AS section,
            'imported_rows'::text AS metric,
            NULL::text AS batch_code,
            NULL::text AS keyword,
            NULL::text AS keyword_norm,
            count(*) AS row_count,
            NULL::text AS validation_result,
            NULL::boolean AS needs_manual_review
           FROM row_checks
        UNION ALL
         SELECT 'summary'::text,
            'matched_to_keyword_master'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            count(*) FILTER (WHERE (row_checks.keyword_id IS NOT NULL)) AS count,
            NULL::text,
            NULL::boolean
           FROM row_checks
        UNION ALL
         SELECT 'summary'::text,
            'not_matched_to_keyword_master'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            count(*) FILTER (WHERE (row_checks.keyword_id IS NULL)) AS count,
            NULL::text,
            NULL::boolean
           FROM row_checks
        UNION ALL
         SELECT 'summary'::text,
            'ready_for_snapshot'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            count(*) FILTER (WHERE (row_checks.validation_result = 'ready_for_snapshot'::text)) AS count,
            NULL::text,
            NULL::boolean
           FROM row_checks
        UNION ALL
         SELECT 'summary'::text,
            'missing_metrics'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            count(*) FILTER (WHERE (row_checks.validation_result = 'missing_metrics'::text)) AS count,
            NULL::text,
            NULL::boolean
           FROM row_checks
        UNION ALL
         SELECT 'summary'::text,
            'competition_value_needs_review'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            count(*) FILTER (WHERE (row_checks.validation_result = 'competition_value_needs_review'::text)) AS count,
            NULL::text,
            NULL::boolean
           FROM row_checks
        UNION ALL
         SELECT 'summary'::text,
            'needs_manual_review'::text,
            NULL::text,
            NULL::text,
            NULL::text,
            count(*) FILTER (WHERE (row_checks.needs_manual_review IS TRUE)) AS count,
            NULL::text,
            NULL::boolean
           FROM row_checks
        ), detail AS (
         SELECT 'detail'::text AS section,
            COALESCE(row_checks.validation_result, 'unknown'::text) AS metric,
            row_checks.batch_code,
            COALESCE(row_checks.keyword, row_checks.master_keyword) AS keyword,
            row_checks.keyword_norm_clean AS keyword_norm,
            NULL::bigint AS row_count,
            row_checks.validation_result,
            row_checks.needs_manual_review
           FROM row_checks
        )
 SELECT summary.section,
    summary.metric,
    summary.batch_code,
    summary.keyword,
    summary.keyword_norm,
    summary.row_count,
    summary.validation_result,
    summary.needs_manual_review
   FROM summary
UNION ALL
 SELECT detail.section,
    detail.metric,
    detail.batch_code,
    detail.keyword,
    detail.keyword_norm,
    detail.row_count,
    detail.validation_result,
    detail.needs_manual_review
   FROM detail;

create or replace view public.feya_commerce_v_seo_keyword_metric_validation_queue_v1 as
 WITH latest_cleanup AS (
         SELECT c_1.cleanup_id,
            c_1.run_id,
            c_1.keyword_id,
            c_1.keyword_norm,
            c_1.original_keyword,
            c_1.cleaned_keyword,
            c_1.suggested_keyword,
            c_1.keyword_axis,
            c_1.keyword_pattern,
            c_1.suggested_page_level,
            c_1.ai_intent,
            c_1.ai_rewrite_status,
            c_1.should_validate_api,
            c_1.should_use_for_product,
            c_1.should_use_for_collection,
            c_1.should_use_for_image_alt,
            c_1.should_hold,
            c_1.warning_flags,
            c_1.ai_reason,
            c_1.model_name,
            c_1.prompt_version,
            c_1.source_queue_snapshot,
            c_1.raw_ai_response_json,
            c_1.review_status,
            c_1.approved_keyword,
            c_1.approved_keyword_norm,
            c_1.approved_at,
            c_1.approved_by,
            c_1.created_at,
            c_1.updated_at,
            row_number() OVER (PARTITION BY c_1.keyword_norm ORDER BY c_1.created_at DESC, c_1.cleanup_id DESC) AS rn
           FROM feya_commerce_seo_keyword_ai_cleanup_v1 c_1
        ), latest_metrics AS (
         SELECT m.snapshot_id,
            m.keyword_norm,
            m.source_api,
            m.geo,
            m.language,
            m.avg_monthly_searches,
            m.competition,
            m.competition_index,
            m.low_top_of_page_bid,
            m.high_top_of_page_bid,
            m.monthly_search_volumes_json,
            m.fetched_at,
            m.raw_payload_json,
            m.data_freshness_status,
            m.created_at,
            row_number() OVER (PARTITION BY m.keyword_norm, m.geo, m.language ORDER BY m.fetched_at DESC, m.snapshot_id DESC) AS rn
           FROM (SELECT "snapshot_id", "keyword_norm", "source_api", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_json", "fetched_at", "raw_payload_json", "data_freshness_status", "created_at", "metric_batch_id", "metric_batch_keyword_id", "keyword_id", "source_request_id", "api_version", "ingestion_run_id", "targeting_context_hash", "access_model", "bid_currency_code" FROM public.feya_commerce_seo_keyword_metric_snapshots_v1 WHERE demand_observation_key IS NULL) AS m
        )
 SELECT c.cleanup_id,
    c.keyword_id,
    c.keyword_norm,
    COALESCE(NULLIF(c.suggested_keyword, ''::text), NULLIF(c.cleaned_keyword, ''::text), c.keyword_norm) AS keyword_for_validation,
    c.original_keyword,
    c.cleaned_keyword,
    c.suggested_keyword,
    c.keyword_axis,
    c.keyword_pattern,
    c.suggested_page_level,
    c.ai_intent,
    c.ai_rewrite_status,
    c.should_validate_api,
    c.should_use_for_product,
    c.should_use_for_collection,
    c.should_use_for_image_alt,
    c.should_hold,
    c.warning_flags,
    c.ai_reason,
    c.review_status,
    COALESCE(lm.geo, 'US'::text) AS metric_geo,
    COALESCE(lm.language, 'en'::text) AS metric_language,
    lm.avg_monthly_searches,
    lm.competition,
    lm.competition_index,
    lm.low_top_of_page_bid,
    lm.high_top_of_page_bid,
    lm.fetched_at AS latest_metric_fetched_at,
        CASE
            WHEN c.should_hold THEN 'hold'::text
            WHEN (c.should_validate_api IS NOT TRUE) THEN 'no_metric_needed'::text
            WHEN (lm.snapshot_id IS NULL) THEN 'needs_metric_import'::text
            WHEN (COALESCE(lm.data_freshness_status, ''::text) = ANY (ARRAY['api_not_connected'::text, 'placeholder'::text, 'mock'::text, 'no_real_metrics'::text])) THEN 'needs_metric_import'::text
            WHEN ((lm.avg_monthly_searches IS NULL) AND (lm.competition IS NULL) AND (lm.competition_index IS NULL)) THEN 'needs_metric_import'::text
            WHEN (lm.fetched_at < (now() - '90 days'::interval)) THEN 'metrics_stale'::text
            ELSE 'has_fresh_metrics'::text
        END AS metric_validation_status,
    c.created_at AS cleanup_created_at,
    c.updated_at AS cleanup_updated_at,
    lm.data_freshness_status AS metric_data_freshness_status
   FROM (latest_cleanup c
     LEFT JOIN latest_metrics lm ON (((lm.keyword_norm = c.keyword_norm) AND (lm.rn = 1))))
  WHERE ((c.rn = 1) AND (c.review_status = ANY (ARRAY['pending'::text, 'needs_review'::text])) AND (c.should_validate_api IS TRUE) AND (c.should_hold IS FALSE));

create or replace view public.feya_commerce_v_seo_keyword_p1_guarded_promotion_dry_run_v1 as
 WITH p1_batches(batch_code) AS (
         VALUES ('P1_CRITICAL_BATCH_01_GOOGLE_ADS_2026_07_08'::text), ('P1_CRITICAL_BATCH_02_GOOGLE_ADS_2026_07_08'::text), ('P1_CRITICAL_BATCH_03_GOOGLE_ADS_2026_07_08'::text)
        ), latest_staging_ranked AS (
         SELECT regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS keyword_norm_clean,
            s.batch_code,
            s.keyword,
            s.avg_monthly_searches,
            s.competition,
            s.competition_index,
            s.low_top_of_page_bid,
            s.high_top_of_page_bid,
            s.imported_at,
            s.import_status,
            s.import_note,
            s.source_file_name,
            "substring"(COALESCE(s.monthly_search_volumes_raw, ''::text), '"source_row_type"\s*:\s*"([^"]+)"'::text) AS source_row_type,
            "substring"(COALESCE(s.monthly_search_volumes_raw, ''::text), '"currency"\s*:\s*"([^"]+)"'::text) AS bid_currency,
            "substring"(COALESCE(s.monthly_search_volumes_raw, ''::text), '"metric_source"\s*:\s*"([^"]+)"'::text) AS metric_source,
            row_number() OVER (PARTITION BY (regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text)) ORDER BY
                CASE
                    WHEN (s.avg_monthly_searches IS NOT NULL) THEN 1
                    ELSE 2
                END, s.imported_at DESC NULLS LAST, s.import_row_id DESC) AS rn
           FROM ((SELECT "import_row_id", "batch_code", "keyword", "keyword_norm", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_raw", "source_file_name", "imported_at", "import_status", "import_note", "created_at" FROM public.feya_commerce_seo_keyword_metric_import_staging_v1 WHERE demand_observation_key IS NULL) AS s
             JOIN p1_batches b ON ((b.batch_code = s.batch_code)))
          WHERE (NULLIF(regexp_replace(lower(btrim(COALESCE(s.keyword_norm, s.keyword, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL)
        ), latest_staging AS (
         SELECT latest_staging_ranked.keyword_norm_clean,
            latest_staging_ranked.batch_code,
            latest_staging_ranked.keyword,
            latest_staging_ranked.avg_monthly_searches,
            latest_staging_ranked.competition,
            latest_staging_ranked.competition_index,
            latest_staging_ranked.low_top_of_page_bid,
            latest_staging_ranked.high_top_of_page_bid,
            latest_staging_ranked.imported_at,
            latest_staging_ranked.import_status,
            latest_staging_ranked.import_note,
            latest_staging_ranked.source_file_name,
            latest_staging_ranked.source_row_type,
            latest_staging_ranked.bid_currency,
            latest_staging_ranked.metric_source,
            latest_staging_ranked.rn
           FROM latest_staging_ranked
          WHERE (latest_staging_ranked.rn = 1)
        ), latest_snapshot_ranked AS (
         SELECT regexp_replace(lower(btrim(COALESCE(m.keyword_norm, ''::text))), '\s+'::text, ' '::text, 'g'::text) AS keyword_norm_clean,
            m.keyword_norm,
            m.avg_monthly_searches,
            m.competition,
            m.competition_index,
            m.low_top_of_page_bid,
            m.high_top_of_page_bid,
            m.fetched_at,
            m.source_api,
            m.raw_payload_json,
            (m.raw_payload_json ->> 'batch_code'::text) AS batch_code,
                CASE
                    WHEN ((m.raw_payload_json ->> 'import_row_id'::text) ~ '^[0-9]+$'::text) THEN ((m.raw_payload_json ->> 'import_row_id'::text))::bigint
                    ELSE NULL::bigint
                END AS import_row_id,
            row_number() OVER (PARTITION BY (regexp_replace(lower(btrim(COALESCE(m.keyword_norm, ''::text))), '\s+'::text, ' '::text, 'g'::text)) ORDER BY
                CASE
                    WHEN (m.avg_monthly_searches IS NOT NULL) THEN 1
                    ELSE 2
                END, m.fetched_at DESC NULLS LAST, m.snapshot_id DESC) AS rn
           FROM ((SELECT "snapshot_id", "keyword_norm", "source_api", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_json", "fetched_at", "raw_payload_json", "data_freshness_status", "created_at", "metric_batch_id", "metric_batch_keyword_id", "keyword_id", "source_request_id", "api_version", "ingestion_run_id", "targeting_context_hash", "access_model", "bid_currency_code" FROM public.feya_commerce_seo_keyword_metric_snapshots_v1 WHERE demand_observation_key IS NULL) AS m
             JOIN p1_batches b ON ((b.batch_code = (m.raw_payload_json ->> 'batch_code'::text))))
          WHERE (NULLIF(regexp_replace(lower(btrim(COALESCE(m.keyword_norm, ''::text))), '\s+'::text, ' '::text, 'g'::text), ''::text) IS NOT NULL)
        ), latest_snapshot AS (
         SELECT m.keyword_norm_clean,
            m.keyword_norm,
            m.avg_monthly_searches,
            m.competition,
            m.competition_index,
            m.low_top_of_page_bid,
            m.high_top_of_page_bid,
            m.fetched_at,
            m.source_api,
            m.raw_payload_json,
            m.batch_code,
            m.import_row_id,
            m.rn,
            st.source_row_type AS staging_source_row_type,
            st.bid_currency AS staging_bid_currency,
            st.metric_source AS staging_metric_source,
            st.source_file_name AS staging_source_file_name,
            st.import_status AS staging_import_status,
            st.import_note AS staging_import_note
           FROM (latest_snapshot_ranked m
             LEFT JOIN latest_staging st ON ((st.keyword_norm_clean = m.keyword_norm_clean)))
          WHERE (m.rn = 1)
        ), p1_metric_keywords AS (
         SELECT latest_staging.keyword_norm_clean
           FROM latest_staging
        UNION
         SELECT latest_snapshot.keyword_norm_clean
           FROM latest_snapshot
        ), bank_best_ranked AS (
         SELECT b.keyword_norm,
            b.review_status,
            b.bank_bucket,
            b.page_type,
            b.role,
            b.role_label,
            b.avg_monthly_searches,
            b.competition,
            b.competition_index,
            b.metric_source,
            b.low_bid,
            b.high_bid,
            b.updated_at,
            row_number() OVER (PARTITION BY b.keyword_norm ORDER BY
                CASE b.review_status
                    WHEN 'approved_draft'::text THEN 1
                    WHEN 'hold'::text THEN 2
                    WHEN 'reject'::text THEN 3
                    ELSE 9
                END, b.avg_monthly_searches DESC NULLS LAST, b.updated_at DESC NULLS LAST) AS rn
           FROM seo_keyword_bank_v1 b
        ), bank_best AS (
         SELECT bank_best_ranked.keyword_norm,
            bank_best_ranked.review_status,
            bank_best_ranked.bank_bucket,
            bank_best_ranked.page_type,
            bank_best_ranked.role,
            bank_best_ranked.role_label,
            bank_best_ranked.avg_monthly_searches,
            bank_best_ranked.competition,
            bank_best_ranked.competition_index,
            bank_best_ranked.metric_source,
            bank_best_ranked.low_bid,
            bank_best_ranked.high_bid,
            bank_best_ranked.updated_at,
            bank_best_ranked.rn
           FROM bank_best_ranked
          WHERE (bank_best_ranked.rn = 1)
        ), lm_norms AS (
         SELECT DISTINCT vw_seo_keyword_bank_v1_for_listing_master.keyword_norm
           FROM vw_seo_keyword_bank_v1_for_listing_master
        ), base AS (
         SELECT v2.candidate_keyword,
            v2.candidate_keyword_norm,
            v2.candidate_source,
            v2.source_batch,
            v2.source_row_type,
            v2.exists_in_bank,
            v2.exists_in_listing_master,
            v2.has_metric,
            v2.avg_monthly_searches,
            v2.competition,
            v2.competition_index,
            v2.low_bid,
            v2.high_bid,
            v2.bid_currency,
            v2.metric_source,
            v2.metric_date,
            v2.source_review_status,
            v2.source_validation_status,
            v2.cleanup_pipeline_status,
            v2.source_bank_bucket,
            v2.source_page_type,
            v2.source_role,
            v2.source_role_label,
            v2.proposed_bank_bucket,
            v2.proposed_review_status,
            v2.block_flags,
            v2.dry_run_action,
            v2.reason,
            v2.source_clusters,
            v2.source_files,
            v2.source_reason,
            v2.source_notes,
            v2.raw_json,
            COALESCE(ls.batch_code, st.batch_code, v2.source_batch) AS p1_source_batch,
            COALESCE(ls.staging_source_row_type, st.source_row_type, v2.source_row_type) AS p1_source_row_type,
            COALESCE(ls.avg_monthly_searches, st.avg_monthly_searches, v2.avg_monthly_searches) AS p1_avg_monthly_searches,
            COALESCE(NULLIF(ls.competition, ''::text), NULLIF(st.competition, ''::text), NULLIF(v2.competition, ''::text)) AS p1_competition,
            COALESCE(ls.competition_index, st.competition_index, v2.competition_index) AS p1_competition_index,
            COALESCE(ls.low_top_of_page_bid, st.low_top_of_page_bid, v2.low_bid) AS p1_low_bid,
            COALESCE(ls.high_top_of_page_bid, st.high_top_of_page_bid, v2.high_bid) AS p1_high_bid,
            COALESCE(ls.staging_bid_currency, st.bid_currency, v2.bid_currency) AS p1_bid_currency,
            COALESCE(ls.staging_metric_source, st.metric_source, v2.metric_source, ls.source_api) AS p1_metric_source,
            COALESCE(ls.fetched_at, st.imported_at, v2.metric_date) AS p1_metric_date,
            bb.review_status AS current_bank_review_status,
            bb.bank_bucket AS current_bank_bucket,
            bb.page_type AS current_page_type,
            (lm.keyword_norm IS NOT NULL) AS current_visible_in_listing_master
           FROM ((((feya_commerce_v_seo_keyword_candidate_promotion_dry_run_v2 v2
             LEFT JOIN latest_snapshot ls ON ((ls.keyword_norm_clean = v2.candidate_keyword_norm)))
             LEFT JOIN latest_staging st ON ((st.keyword_norm_clean = v2.candidate_keyword_norm)))
             LEFT JOIN bank_best bb ON ((bb.keyword_norm = v2.candidate_keyword_norm)))
             LEFT JOIN lm_norms lm ON ((lm.keyword_norm = v2.candidate_keyword_norm)))
          WHERE ((v2.source_batch IN ( SELECT p1_batches.batch_code
                   FROM p1_batches)) OR (v2.candidate_keyword_norm IN ( SELECT p1_metric_keywords.keyword_norm_clean
                   FROM p1_metric_keywords)))
        ), classified AS (
         SELECT b.candidate_keyword,
            b.candidate_keyword_norm,
            b.candidate_source,
            b.source_batch,
            b.source_row_type,
            b.exists_in_bank,
            b.exists_in_listing_master,
            b.has_metric,
            b.avg_monthly_searches,
            b.competition,
            b.competition_index,
            b.low_bid,
            b.high_bid,
            b.bid_currency,
            b.metric_source,
            b.metric_date,
            b.source_review_status,
            b.source_validation_status,
            b.cleanup_pipeline_status,
            b.source_bank_bucket,
            b.source_page_type,
            b.source_role,
            b.source_role_label,
            b.proposed_bank_bucket,
            b.proposed_review_status,
            b.block_flags,
            b.dry_run_action,
            b.reason,
            b.source_clusters,
            b.source_files,
            b.source_reason,
            b.source_notes,
            b.raw_json,
            b.p1_source_batch,
            b.p1_source_row_type,
            b.p1_avg_monthly_searches,
            b.p1_competition,
            b.p1_competition_index,
            b.p1_low_bid,
            b.p1_high_bid,
            b.p1_bid_currency,
            b.p1_metric_source,
            b.p1_metric_date,
            b.current_bank_review_status,
            b.current_bank_bucket,
            b.current_page_type,
            b.current_visible_in_listing_master,
                CASE
                    WHEN (b.exists_in_bank OR (b.dry_run_action = 'excluded_duplicate'::text)) THEN 'EXISTING_BANK_REVIEW'::text
                    WHEN (b.dry_run_action = 'would_insert'::text) THEN 'NEW_INSERT_CANDIDATE'::text
                    ELSE 'HOLD_OR_BLOCKED_REVIEW'::text
                END AS review_group,
                CASE
                    WHEN (b.proposed_bank_bucket = ANY (ARRAY['product_or_alt'::text, 'product'::text, 'collection'::text, 'commercial_collection'::text, 'visual_collection'::text, 'faq'::text])) THEN b.proposed_bank_bucket
                    ELSE 'hold'::text
                END AS proposed_page_type_calc,
            ((b.dry_run_action = 'would_insert'::text) AND (COALESCE(b.p1_source_row_type, b.source_row_type) = 'input_seed'::text) AND (COALESCE(b.p1_avg_monthly_searches, b.avg_monthly_searches) IS NOT NULL) AND (COALESCE(b.p1_competition, b.competition) IS NOT NULL) AND (upper(COALESCE(b.p1_competition, b.competition)) <> 'UNKNOWN'::text) AND (b.proposed_bank_bucket = ANY (ARRAY['product'::text, 'product_or_alt'::text, 'collection'::text, 'commercial_collection'::text, 'visual_collection'::text, 'faq'::text])) AND (COALESCE(jsonb_array_length(b.block_flags), 0) = 0) AND (b.exists_in_bank = false)) AS proposed_insert_allowed_calc
           FROM base b
        ), scored AS (
         SELECT c.candidate_keyword,
            c.candidate_keyword_norm,
            c.candidate_source,
            c.source_batch,
            c.source_row_type,
            c.exists_in_bank,
            c.exists_in_listing_master,
            c.has_metric,
            c.avg_monthly_searches,
            c.competition,
            c.competition_index,
            c.low_bid,
            c.high_bid,
            c.bid_currency,
            c.metric_source,
            c.metric_date,
            c.source_review_status,
            c.source_validation_status,
            c.cleanup_pipeline_status,
            c.source_bank_bucket,
            c.source_page_type,
            c.source_role,
            c.source_role_label,
            c.proposed_bank_bucket,
            c.proposed_review_status,
            c.block_flags,
            c.dry_run_action,
            c.reason,
            c.source_clusters,
            c.source_files,
            c.source_reason,
            c.source_notes,
            c.raw_json,
            c.p1_source_batch,
            c.p1_source_row_type,
            c.p1_avg_monthly_searches,
            c.p1_competition,
            c.p1_competition_index,
            c.p1_low_bid,
            c.p1_high_bid,
            c.p1_bid_currency,
            c.p1_metric_source,
            c.p1_metric_date,
            c.current_bank_review_status,
            c.current_bank_bucket,
            c.current_page_type,
            c.current_visible_in_listing_master,
            c.review_group,
            c.proposed_page_type_calc,
            c.proposed_insert_allowed_calc,
            LEAST(100, GREATEST(0, ((((50 +
                CASE
                    WHEN (COALESCE(c.p1_avg_monthly_searches, c.avg_monthly_searches) >= 300) THEN 25
                    WHEN (COALESCE(c.p1_avg_monthly_searches, c.avg_monthly_searches) >= 100) THEN 18
                    WHEN (COALESCE(c.p1_avg_monthly_searches, c.avg_monthly_searches) >= 50) THEN 12
                    WHEN (COALESCE(c.p1_avg_monthly_searches, c.avg_monthly_searches) >= 20) THEN 8
                    WHEN (COALESCE(c.p1_avg_monthly_searches, c.avg_monthly_searches) >= 10) THEN 4
                    ELSE 0
                END) +
                CASE upper(COALESCE(c.p1_competition, c.competition, ''::text))
                    WHEN 'LOW'::text THEN 12
                    WHEN 'MEDIUM'::text THEN 8
                    WHEN 'HIGH'::text THEN 2
                    ELSE 0
                END) +
                CASE c.proposed_bank_bucket
                    WHEN 'product_or_alt'::text THEN 8
                    WHEN 'product'::text THEN 6
                    WHEN 'collection'::text THEN 4
                    ELSE 0
                END) +
                CASE COALESCE(c.p1_source_row_type, c.source_row_type)
                    WHEN 'input_seed'::text THEN 5
                    ELSE 0
                END))) AS proposed_score_calc
           FROM classified c
        )
 SELECT review_group,
    candidate_keyword,
    candidate_keyword_norm,
    p1_source_batch AS source_batch,
    COALESCE(p1_source_row_type, source_row_type) AS source_row_type,
    dry_run_action,
    exists_in_bank,
    exists_in_listing_master,
    proposed_insert_allowed_calc AS proposed_insert_allowed,
    proposed_bank_bucket,
    proposed_page_type_calc AS proposed_page_type,
        CASE
            WHEN proposed_insert_allowed_calc THEN 'approved_draft'::text
            WHEN (COALESCE(p1_source_row_type, source_row_type) = 'google_ads_related_idea'::text) THEN 'hold'::text
            WHEN (dry_run_action = ANY (ARRAY['needs_manual_review_no_metric'::text, 'needs_manual_review_zero_metric'::text])) THEN 'hold'::text
            WHEN (dry_run_action = 'excluded_noise'::text) THEN 'reject'::text
            WHEN exists_in_bank THEN COALESCE(current_bank_review_status, 'existing_bank_review'::text)
            ELSE COALESCE(proposed_review_status, 'hold'::text)
        END AS proposed_review_status,
    proposed_score_calc AS proposed_score,
    p1_avg_monthly_searches AS avg_monthly_searches,
    p1_competition AS competition,
    p1_competition_index AS competition_index,
    p1_bid_currency AS bid_currency,
    p1_low_bid AS low_bid,
    p1_high_bid AS high_bid,
    p1_metric_source AS metric_source,
    p1_metric_date AS metric_date,
        CASE
            WHEN ((p1_bid_currency IS NOT NULL) AND (p1_bid_currency <> 'USD'::text)) THEN 'UAH bids preserved for provenance only; do not copy to seo_keyword_bank_v1 until currency-aware logic exists'::text
            WHEN (p1_bid_currency IS NOT NULL) THEN 'Bid fields preserved for provenance only; promotion payload must not copy low_bid/high_bid in this dry-run'::text
            ELSE NULL::text
        END AS do_not_copy_bid_reason,
        CASE
            WHEN proposed_insert_allowed_calc THEN NULL::text
            WHEN (exists_in_bank OR (dry_run_action = 'excluded_duplicate'::text)) THEN 'already_exists_in_bank_no_insert'::text
            WHEN (COALESCE(jsonb_array_length(block_flags), 0) > 0) THEN ('blocked_by_flags: '::text || (block_flags)::text)
            WHEN (COALESCE(p1_source_row_type, source_row_type) = 'google_ads_related_idea'::text) THEN 'google_ads_related_idea_requires_manual_review'::text
            WHEN ((p1_avg_monthly_searches IS NULL) OR (p1_competition IS NULL) OR (upper(p1_competition) = 'UNKNOWN'::text)) THEN 'no_usable_metric'::text
            WHEN (proposed_bank_bucket <> ALL (ARRAY['product'::text, 'product_or_alt'::text, 'collection'::text, 'commercial_collection'::text, 'visual_collection'::text, 'faq'::text])) THEN 'unsafe_or_hold_bucket'::text
            WHEN (proposed_review_status = ANY (ARRAY['hold'::text, 'reject'::text])) THEN 'review_status_not_approved'::text
            ELSE 'not_allowed_by_guard'::text
        END AS insert_block_reason,
        CASE
            WHEN (exists_in_bank AND exists_in_listing_master) THEN 'already_visible_update_metrics_only'::text
            WHEN (exists_in_bank AND (NOT exists_in_listing_master)) THEN 'bank_exists_but_not_listing_master_check_status_bucket'::text
            ELSE 'not_existing'::text
        END AS existing_bank_review_action,
    reason,
    (raw_json || jsonb_build_object('p1_source_batch', p1_source_batch, 'p1_source_row_type', COALESCE(p1_source_row_type, source_row_type), 'p1_metric_values', jsonb_build_object('avg_monthly_searches', p1_avg_monthly_searches, 'competition', p1_competition, 'competition_index', p1_competition_index, 'bid_currency', p1_bid_currency, 'low_bid', p1_low_bid, 'high_bid', p1_high_bid), 'current_bank', jsonb_build_object('review_status', current_bank_review_status, 'bank_bucket', current_bank_bucket, 'page_type', current_page_type, 'visible_in_listing_master', current_visible_in_listing_master), 'proposed_insert_allowed', proposed_insert_allowed_calc, 'proposed_score', proposed_score_calc, 'insert_payload_excludes_bid_fields', true)) AS raw_json
   FROM scored;

create or replace view public.feya_commerce_v_seo_metric_system_status_v1 as
 SELECT 'cleanup_candidates'::text AS section,
    'needs_human_review'::text AS metric,
    count(*) AS value
   FROM feya_commerce_v_seo_keyword_ai_cleanup_report_v1
  WHERE (feya_commerce_v_seo_keyword_ai_cleanup_report_v1.cleanup_pipeline_status = 'needs_human_review'::text)
UNION ALL
 SELECT 'cleanup_candidates'::text AS section,
    'needs_ai_cleanup'::text AS metric,
    count(*) AS value
   FROM feya_commerce_v_seo_keyword_ai_cleanup_report_v1
  WHERE (feya_commerce_v_seo_keyword_ai_cleanup_report_v1.cleanup_pipeline_status = 'needs_ai_cleanup'::text)
UNION ALL
 SELECT 'metric_validation'::text AS section,
    feya_commerce_v_seo_keyword_metric_validation_queue_v1.metric_validation_status AS metric,
    count(*) AS value
   FROM feya_commerce_v_seo_keyword_metric_validation_queue_v1
  GROUP BY feya_commerce_v_seo_keyword_metric_validation_queue_v1.metric_validation_status
UNION ALL
 SELECT 'metric_import_staging'::text AS section,
    COALESCE(feya_commerce_seo_keyword_metric_import_staging_v1.import_status, 'null_status'::text) AS metric,
    count(*) AS value
   FROM (SELECT "import_row_id", "batch_code", "keyword", "keyword_norm", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_raw", "source_file_name", "imported_at", "import_status", "import_note", "created_at" FROM public.feya_commerce_seo_keyword_metric_import_staging_v1 WHERE demand_observation_key IS NULL) AS feya_commerce_seo_keyword_metric_import_staging_v1
  GROUP BY COALESCE(feya_commerce_seo_keyword_metric_import_staging_v1.import_status, 'null_status'::text)
UNION ALL
 SELECT 'score_preview'::text AS section,
    'score_ready_rows'::text AS metric,
    count(*) AS value
   FROM feya_commerce_v_seo_keyword_score_preview_v1;

create or replace view public.feya_v_kw_product_fact_expansion_candidates_v1 as
 WITH product_source AS (
         SELECT q.brief_queue_id,
            q.canonical_product_id,
            s.product_slug,
            q.matched_etsy_listing_id,
            q.current_title AS product_title,
            q.h1,
            q.card_title,
            q.product_type,
            COALESCE((q.safe_compact_payload_json #>> '{product_facts,final_primary_part_v2}'::text[]), (q.safe_compact_payload_json #>> '{product_facts,final_primary_part}'::text[]), (q.safe_compact_payload_json #>> '{product_facts,derived_primary_part}'::text[])) AS final_primary_part,
            COALESCE((q.safe_compact_payload_json #>> '{product_facts,final_material_primary_v2}'::text[]), (q.safe_compact_payload_json #>> '{product_facts,final_material_primary}'::text[]), q.normalized_material_primary) AS material_detail,
            COALESCE((q.safe_compact_payload_json #>> '{product_facts,final_color_primary_v2}'::text[]), (q.safe_compact_payload_json #>> '{product_facts,final_color_primary}'::text[]), q.normalized_color_primary) AS color,
            q.product_fact_quality_status,
            lower(((((((((COALESCE(q.current_title, ''::text) || ' '::text) || COALESCE(q.h1, ''::text)) || ' '::text) || COALESCE(q.card_title, ''::text)) || ' '::text) || COALESCE((q.raw_ai_context)::text, ''::text)) || ' '::text) || COALESCE((q.safe_compact_payload_json)::text, ''::text))) AS product_text,
            lower(((COALESCE((q.safe_compact_payload_json #>> '{product_facts,final_primary_part_v2}'::text[]), ''::text) || ' '::text) || COALESCE((q.safe_compact_payload_json #>> '{product_facts,final_primary_part}'::text[]), ''::text))) AS final_primary_part_text,
            lower((((COALESCE((q.safe_compact_payload_json #> '{product_facts,final_product_facts_v2,title_derivation,derived_component_tags}'::text[]), '[]'::jsonb))::text || ' '::text) || (COALESCE((q.safe_compact_payload_json #> '{product_facts,derived_product_facts,derived_component_tags}'::text[]), '[]'::jsonb))::text)) AS derived_component_text,
            lower(((COALESCE((q.public_configurations_json)::text, ''::text) || ' '::text) || (COALESCE((q.safe_compact_payload_json #> '{product_facts,final_product_facts_v2,configuration_derivation,public_config_components}'::text[]), '[]'::jsonb))::text)) AS configuration_component_text,
            d.do_not_publish_flag,
            d.publish_status,
            d.readiness_status AS detail_readiness_status
           FROM ((feya_commerce_v_product_seo_brief_safe_generation_queue_v1 q
             LEFT JOIN feya_commerce_v_step7_storefront_products_api s ON ((s.canonical_product_id = q.canonical_product_id)))
             LEFT JOIN feya_commerce_v_step6_product_builder_detail d ON ((d.canonical_product_id = q.canonical_product_id)))
        ), product_terms AS (
         SELECT ps.brief_queue_id,
            ps.canonical_product_id,
            ps.product_slug,
            ps.matched_etsy_listing_id,
            ps.product_title,
            ps.h1,
            ps.card_title,
            ps.product_type,
            ps.final_primary_part,
            ps.material_detail,
            ps.color,
            ps.product_fact_quality_status,
            ps.product_text,
            ps.final_primary_part_text,
            ps.derived_component_text,
            ps.configuration_component_text,
            ps.do_not_publish_flag,
            ps.publish_status,
            ps.detail_readiness_status,
                CASE
                    WHEN (ps.product_text ~ 'burning man'::text) THEN 'Burning Man'::text
                    WHEN (ps.product_text ~ '(festival|rave|edm|edc|coachella|tomorrowland|club)'::text) THEN 'Festival/Rave'::text
                    WHEN (ps.product_text ~ '(stage|performance|performer|dance|show|dj|burlesque|drag)'::text) THEN 'Stage/Performance'::text
                    WHEN (ps.product_text ~ '(editorial|red carpet|fashion)'::text) THEN 'Fashion/Editorial/Red Carpet'::text
                    WHEN (ps.product_text ~ 'cosplay'::text) THEN 'Cosplay'::text
                    ELSE NULL::text
                END AS context_primary,
                CASE
                    WHEN (ps.product_text ~ '(cyberpunk|cyber)'::text) THEN 'cyberpunk'::text
                    WHEN (ps.product_text ~ 'futuristic'::text) THEN 'futuristic'::text
                    WHEN (ps.product_text ~ '(desert|dune|apocalyptic|mad max)'::text) THEN 'desert apocalyptic'::text
                    WHEN (ps.product_text ~ '(goth|gothic)'::text) THEN 'gothic'::text
                    WHEN (ps.product_text ~ 'punk'::text) THEN 'punk'::text
                    WHEN (ps.product_text ~ '(glam|high fashion)'::text) THEN 'glam'::text
                    ELSE NULL::text
                END AS context_secondary,
                CASE
                    WHEN (ps.product_text ~ 'drag'::text) THEN 'drag queen'::text
                    WHEN (ps.product_text ~ 'warrior'::text) THEN 'warrior'::text
                    WHEN (ps.product_text ~ 'goddess'::text) THEN 'goddess'::text
                    WHEN (ps.product_text ~ 'alien'::text) THEN 'alien'::text
                    WHEN (ps.product_text ~ 'demon'::text) THEN 'demon'::text
                    WHEN (ps.product_text ~ 'angel'::text) THEN 'angel'::text
                    WHEN (ps.product_text ~ 'queen'::text) THEN 'queen'::text
                    ELSE NULL::text
                END AS persona,
                CASE
                    WHEN (lower(((((COALESCE(ps.product_title, ''::text) || ' '::text) || COALESCE(ps.h1, ''::text)) || ' '::text) || COALESCE(ps.card_title, ''::text))) ~ '(digital download|ai try on|preview from your photo|photo \+ 5 sec video|photo \+ video|video preview|individual sizes|delivery for|shipping|service item|sampler|probnik)'::text) THEN true
                    WHEN (COALESCE(ps.do_not_publish_flag, false) = true) THEN true
                    WHEN (lower(((COALESCE(ps.detail_readiness_status, ''::text) || ' '::text) || COALESCE(ps.publish_status, ''::text))) ~ '(storefront_excluded|do_not_publish)'::text) THEN true
                    ELSE false
                END AS product_not_seo_target_flag,
            lower(((((COALESCE(ps.final_primary_part_text, ''::text) || ' '::text) || COALESCE(ps.derived_component_text, ''::text)) || ' '::text) || COALESCE(ps.configuration_component_text, ''::text))) AS confirmed_component_text,
            lower(COALESCE(ps.material_detail, ''::text)) AS material_l,
            lower(COALESCE(ps.color, ''::text)) AS color_l
           FROM product_source ps
        ), product_arrays AS (
         SELECT pt.brief_queue_id,
            pt.canonical_product_id,
            pt.product_slug,
            pt.matched_etsy_listing_id,
            pt.product_title,
            pt.h1,
            pt.card_title,
            pt.product_type,
            pt.final_primary_part,
            pt.material_detail,
            pt.color,
            pt.product_fact_quality_status,
            pt.product_text,
            pt.final_primary_part_text,
            pt.derived_component_text,
            pt.configuration_component_text,
            pt.do_not_publish_flag,
            pt.publish_status,
            pt.detail_readiness_status,
            pt.context_primary,
            pt.context_secondary,
            pt.persona,
            pt.product_not_seo_target_flag,
            pt.confirmed_component_text,
            pt.material_l,
            pt.color_l,
            array_remove(ARRAY[
                CASE
                    WHEN (pt.confirmed_component_text ~ '(top|breastplate|chest plate)'::text) THEN 'top'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((pt.confirmed_component_text ~ 'corset'::text) OR (pt.product_text ~ '(corset|breastplate|chest plate|overbust)'::text)) THEN 'corset'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.product_text ~ '(breastplate|chest plate)'::text) THEN 'chest plate'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'harness'::text) THEN 'harness'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'skirt'::text) THEN 'skirt'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'panties'::text) THEN 'panties'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ '(garter|leg)'::text) THEN 'leg garters'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ '(choker|collar)'::text) THEN 'choker'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'shoulder'::text) THEN 'shoulder armor'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ '(arm|sleeve|glove|bracer)'::text) THEN 'arm cuffs'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'mask'::text) THEN 'mask'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ '(headpiece|crown|headdress)'::text) THEN 'headpiece'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'wing'::text) THEN 'wings'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'tail'::text) THEN 'tail'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'spine'::text) THEN 'spine'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'bodysuit'::text) THEN 'bodysuit'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (pt.confirmed_component_text ~ 'dress'::text) THEN 'dress'::text
                    ELSE NULL::text
                END], NULL::text) AS component_terms,
                CASE
                    WHEN (pt.material_l ~ '(mirror acrylic|acrylic)'::text) THEN 'mirror acrylic'::text
                    WHEN (pt.material_l ~ 'vegan leather'::text) THEN 'vegan leather'::text
                    WHEN (pt.material_l ~ 'fabric'::text) THEN 'fabric'::text
                    ELSE NULL::text
                END AS safe_material_term,
                CASE
                    WHEN (pt.material_l ~ '(mirror acrylic|acrylic)'::text) THEN 'mirror'::text
                    ELSE NULL::text
                END AS visual_effect_term
           FROM product_terms pt
        ), component_rows AS (
         SELECT pa.brief_queue_id,
            pa.canonical_product_id,
            pa.product_slug,
            pa.matched_etsy_listing_id,
            pa.product_title,
            pa.h1,
            pa.card_title,
            pa.product_type,
            pa.final_primary_part,
            pa.material_detail,
            pa.color,
            pa.product_fact_quality_status,
            pa.product_text,
            pa.final_primary_part_text,
            pa.derived_component_text,
            pa.configuration_component_text,
            pa.do_not_publish_flag,
            pa.publish_status,
            pa.detail_readiness_status,
            pa.context_primary,
            pa.context_secondary,
            pa.persona,
            pa.product_not_seo_target_flag,
            pa.confirmed_component_text,
            pa.material_l,
            pa.color_l,
            pa.component_terms,
            pa.safe_material_term,
            pa.visual_effect_term,
            c.component_term,
            cardinality(pa.component_terms) AS component_count
           FROM (product_arrays pa
             CROSS JOIN LATERAL unnest(pa.component_terms) c(component_term))
          WHERE (NOT pa.product_not_seo_target_flag)
        ), expansion_union AS (
         SELECT component_rows.canonical_product_id,
            component_rows.matched_etsy_listing_id,
            component_rows.product_slug,
            component_rows.product_title,
            component_rows.h1,
            component_rows.card_title,
            component_rows.product_type,
            component_rows.final_primary_part,
            component_rows.material_detail,
            component_rows.color,
            component_rows.context_primary,
            component_rows.context_secondary,
            component_rows.persona,
            component_rows.component_terms,
            component_rows.product_not_seo_target_flag,
            component_rows.product_fact_quality_status,
            component_rows.safe_material_term,
            component_rows.visual_effect_term,
            component_rows.component_term,
            component_rows.component_count,
            'color_material_part'::text AS pattern_code,
            concat_ws(' '::text, NULLIF(component_rows.color_l, ''::text), component_rows.safe_material_term, component_rows.component_term) AS generated_keyword,
            'product'::text AS generated_page_level,
            'exact_product_candidate'::text AS generated_role_hint,
            10 AS pattern_priority,
            'confirmed component + color + material'::text AS expansion_reason
           FROM component_rows
          WHERE ((component_rows.safe_material_term IS NOT NULL) AND (NULLIF(component_rows.color_l, ''::text) IS NOT NULL))
        UNION ALL
         SELECT component_rows.canonical_product_id,
            component_rows.matched_etsy_listing_id,
            component_rows.product_slug,
            component_rows.product_title,
            component_rows.h1,
            component_rows.card_title,
            component_rows.product_type,
            component_rows.final_primary_part,
            component_rows.material_detail,
            component_rows.color,
            component_rows.context_primary,
            component_rows.context_secondary,
            component_rows.persona,
            component_rows.component_terms,
            component_rows.product_not_seo_target_flag,
            component_rows.product_fact_quality_status,
            component_rows.safe_material_term,
            component_rows.visual_effect_term,
            component_rows.component_term,
            component_rows.component_count,
            'material_part'::text,
            concat_ws(' '::text, component_rows.safe_material_term, component_rows.component_term) AS concat_ws,
            'product'::text,
            'exact_product_candidate'::text,
            20,
            'confirmed component + material'::text
           FROM component_rows
          WHERE (component_rows.safe_material_term IS NOT NULL)
        UNION ALL
         SELECT component_rows.canonical_product_id,
            component_rows.matched_etsy_listing_id,
            component_rows.product_slug,
            component_rows.product_title,
            component_rows.h1,
            component_rows.card_title,
            component_rows.product_type,
            component_rows.final_primary_part,
            component_rows.material_detail,
            component_rows.color,
            component_rows.context_primary,
            component_rows.context_secondary,
            component_rows.persona,
            component_rows.component_terms,
            component_rows.product_not_seo_target_flag,
            component_rows.product_fact_quality_status,
            component_rows.safe_material_term,
            component_rows.visual_effect_term,
            component_rows.component_term,
            component_rows.component_count,
            'color_part'::text,
            concat_ws(' '::text, NULLIF(component_rows.color_l, ''::text), component_rows.component_term) AS concat_ws,
            'product'::text,
            'exact_product_candidate'::text,
            30,
            'confirmed component + color'::text
           FROM component_rows
          WHERE (NULLIF(component_rows.color_l, ''::text) IS NOT NULL)
        UNION ALL
         SELECT component_rows.canonical_product_id,
            component_rows.matched_etsy_listing_id,
            component_rows.product_slug,
            component_rows.product_title,
            component_rows.h1,
            component_rows.card_title,
            component_rows.product_type,
            component_rows.final_primary_part,
            component_rows.material_detail,
            component_rows.color,
            component_rows.context_primary,
            component_rows.context_secondary,
            component_rows.persona,
            component_rows.component_terms,
            component_rows.product_not_seo_target_flag,
            component_rows.product_fact_quality_status,
            component_rows.safe_material_term,
            component_rows.visual_effect_term,
            component_rows.component_term,
            component_rows.component_count,
            'visual_effect_part'::text,
            concat_ws(' '::text, component_rows.visual_effect_term, component_rows.component_term) AS concat_ws,
            'image_alt'::text,
            'image_alt_or_product_candidate'::text,
            40,
            'visual/material effect + confirmed component'::text
           FROM component_rows
          WHERE (component_rows.visual_effect_term IS NOT NULL)
        UNION ALL
         SELECT component_rows.canonical_product_id,
            component_rows.matched_etsy_listing_id,
            component_rows.product_slug,
            component_rows.product_title,
            component_rows.h1,
            component_rows.card_title,
            component_rows.product_type,
            component_rows.final_primary_part,
            component_rows.material_detail,
            component_rows.color,
            component_rows.context_primary,
            component_rows.context_secondary,
            component_rows.persona,
