            product_arrays.component_terms[1] AS component_terms,
            cardinality(product_arrays.component_terms) AS cardinality,
            'component_pair'::text,
            concat(product_arrays.component_terms[1], ' and ', product_arrays.component_terms[2]) AS concat,
            'product'::text,
            'component_pair_candidate'::text,
            70,
            'two confirmed components'::text
           FROM product_arrays
          WHERE ((NOT product_arrays.product_not_seo_target_flag) AND (cardinality(product_arrays.component_terms) >= 2))
        UNION ALL
         SELECT product_arrays.canonical_product_id,
            product_arrays.matched_etsy_listing_id,
            product_arrays.product_slug,
            product_arrays.product_title,
            product_arrays.h1,
            product_arrays.card_title,
            product_arrays.product_type,
            product_arrays.final_primary_part,
            product_arrays.material_detail,
            product_arrays.color,
            product_arrays.context_primary,
            product_arrays.context_secondary,
            product_arrays.persona,
            product_arrays.component_terms,
            product_arrays.product_not_seo_target_flag,
            product_arrays.product_fact_quality_status,
            product_arrays.safe_material_term,
            product_arrays.visual_effect_term,
            product_arrays.component_terms[1] AS component_terms,
            cardinality(product_arrays.component_terms) AS cardinality,
            'bundle_look'::text,
                CASE
                    WHEN (product_arrays.context_primary = 'Burning Man'::text) THEN 'burning man outfit set'::text
                    WHEN (product_arrays.context_primary = 'Stage/Performance'::text) THEN 'stage costume set'::text
                    WHEN (product_arrays.material_l ~ '(mirror acrylic|acrylic)'::text) THEN 'mirror outfit set'::text
                    ELSE 'festival outfit set'::text
                END AS "case",
            'collection_or_bundle'::text,
            'bundle_look_candidate'::text,
            80,
            'confirmed multi-component bundle/look; set is not product type'::text
           FROM product_arrays
          WHERE ((NOT product_arrays.product_not_seo_target_flag) AND (cardinality(product_arrays.component_terms) >= 2))
        ), cleaned AS (
         SELECT expansion_union.canonical_product_id,
            expansion_union.matched_etsy_listing_id,
            expansion_union.product_slug,
            expansion_union.product_title,
            expansion_union.h1,
            expansion_union.card_title,
            expansion_union.product_type,
            expansion_union.final_primary_part,
            expansion_union.material_detail,
            expansion_union.color,
            expansion_union.context_primary,
            expansion_union.context_secondary,
            expansion_union.persona,
            expansion_union.component_terms,
            expansion_union.product_not_seo_target_flag,
            expansion_union.product_fact_quality_status,
            expansion_union.safe_material_term,
            expansion_union.visual_effect_term,
            expansion_union.component_term,
            expansion_union.component_count,
            expansion_union.pattern_code,
            expansion_union.generated_keyword,
            expansion_union.generated_page_level,
            expansion_union.generated_role_hint,
            expansion_union.pattern_priority,
            expansion_union.expansion_reason,
            lower(TRIM(BOTH FROM regexp_replace(expansion_union.generated_keyword, '\s+'::text, ' '::text, 'g'::text))) AS generated_keyword_norm
           FROM expansion_union
          WHERE ((expansion_union.generated_keyword IS NOT NULL) AND (TRIM(BOTH FROM expansion_union.generated_keyword) <> ''::text) AND (lower(expansion_union.generated_keyword) !~ '(real leather|genuine leather|natural leather|real metal|metal armor|metal armour|latex|theatre|theater|opera|sports|cultural festival|seasonal peaks)'::text) AND (lower(expansion_union.generated_keyword) !~ '(^|\s)leather(\s|$)'::text))
        ), ranked AS (
         SELECT x.canonical_product_id,
            x.matched_etsy_listing_id,
            x.product_slug,
            x.product_title,
            x.h1,
            x.card_title,
            x.product_type,
            x.final_primary_part,
            x.material_detail,
            x.color,
            x.context_primary,
            x.context_secondary,
            x.persona,
            x.component_terms,
            x.product_not_seo_target_flag,
            x.product_fact_quality_status,
            x.safe_material_term,
            x.visual_effect_term,
            x.component_term,
            x.component_count,
            x.pattern_code,
            x.generated_keyword,
            x.generated_page_level,
            x.generated_role_hint,
            x.pattern_priority,
            x.expansion_reason,
            x.generated_keyword_norm,
            x.dedupe_rank,
            x.product_candidate_rank
           FROM ( SELECT c.canonical_product_id,
                    c.matched_etsy_listing_id,
                    c.product_slug,
                    c.product_title,
                    c.h1,
                    c.card_title,
                    c.product_type,
                    c.final_primary_part,
                    c.material_detail,
                    c.color,
                    c.context_primary,
                    c.context_secondary,
                    c.persona,
                    c.component_terms,
                    c.product_not_seo_target_flag,
                    c.product_fact_quality_status,
                    c.safe_material_term,
                    c.visual_effect_term,
                    c.component_term,
                    c.component_count,
                    c.pattern_code,
                    c.generated_keyword,
                    c.generated_page_level,
                    c.generated_role_hint,
                    c.pattern_priority,
                    c.expansion_reason,
                    c.generated_keyword_norm,
                    row_number() OVER (PARTITION BY c.canonical_product_id, c.generated_keyword_norm ORDER BY c.pattern_priority, c.generated_keyword_norm) AS dedupe_rank,
                    row_number() OVER (PARTITION BY c.canonical_product_id ORDER BY c.pattern_priority, c.generated_keyword_norm) AS product_candidate_rank
                   FROM cleaned c) x
          WHERE ((x.dedupe_rank = 1) AND (x.product_candidate_rank <= 30))
        ), latest_metrics AS (
         SELECT DISTINCT ON (feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm) feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm,
            feya_commerce_seo_keyword_metric_snapshots_v1.snapshot_id,
            feya_commerce_seo_keyword_metric_snapshots_v1.fetched_at,
            feya_commerce_seo_keyword_metric_snapshots_v1.data_freshness_status
           FROM (SELECT "snapshot_id", "keyword_norm", "source_api", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_json", "fetched_at", "raw_payload_json", "data_freshness_status", "created_at", "metric_batch_id", "metric_batch_keyword_id", "keyword_id", "source_request_id", "api_version", "ingestion_run_id", "targeting_context_hash", "access_model", "bid_currency_code" FROM public.feya_commerce_seo_keyword_metric_snapshots_v1 WHERE demand_observation_key IS NULL) AS feya_commerce_seo_keyword_metric_snapshots_v1
          ORDER BY feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm, feya_commerce_seo_keyword_metric_snapshots_v1.fetched_at DESC NULLS LAST, feya_commerce_seo_keyword_metric_snapshots_v1.snapshot_id DESC
        ), metric_batch AS (
         SELECT DISTINCT feya_metric_request_batch_keywords_v1.keyword_norm
           FROM feya_metric_request_batch_keywords_v1
        )
 SELECT r.canonical_product_id,
    r.matched_etsy_listing_id,
    r.product_slug,
    r.product_title,
    r.h1,
    r.card_title,
    r.product_type,
    r.final_primary_part,
    r.final_primary_part AS part,
    r.material_detail,
    r.color,
    r.context_primary,
    r.context_secondary,
    r.persona,
    r.component_terms AS components,
    r.generated_keyword,
    r.generated_keyword_norm,
    r.pattern_code,
    r.generated_page_level,
    r.generated_role_hint,
    'candidate_generated'::text AS expansion_status,
    r.expansion_reason,
    false AS product_not_seo_target_flag,
    'confirmed_component_text'::text AS component_source,
        CASE
            WHEN (r.safe_material_term IS NOT NULL) THEN 'final_material_primary'::text
            ELSE NULL::text
        END AS material_source,
        CASE
            WHEN (r.context_primary IS NOT NULL) THEN 'inferred_canonical_context'::text
            ELSE NULL::text
        END AS context_source,
    (u.kw_universe_id IS NOT NULL) AS already_in_keyword_universe,
    u.kw_universe_id AS keyword_id,
    (lm.snapshot_id IS NOT NULL) AS has_metric_snapshot,
        CASE
            WHEN (u.kw_universe_id IS NULL) THEN 'not_in_universe_yet'::text
            WHEN (lm.snapshot_id IS NOT NULL) THEN 'has_metric_snapshot'::text
            WHEN ((mb.keyword_norm IS NOT NULL) OR (u.metric_status = 'needs_metric_validation'::text)) THEN 'wait_for_metrics'::text
            ELSE COALESCE(u.metric_status, 'needs_metric_validation'::text)
        END AS metric_status,
    (lm.snapshot_id IS NULL) AS needs_metric_validation,
    ((r.pattern_code = ANY (ARRAY['component_pair'::text, 'bundle_look'::text, 'style_part'::text])) OR (r.product_fact_quality_status = ANY (ARRAY['HIGH_RISK_FACT_REVIEW'::text, 'FACT_WARNINGS'::text]))) AS needs_human_review,
    r.product_candidate_rank
   FROM (((ranked r
     LEFT JOIN feya_kw_universe_v1 u ON ((u.keyword_norm = r.generated_keyword_norm)))
     LEFT JOIN latest_metrics lm ON ((lm.keyword_norm = r.generated_keyword_norm)))
     LEFT JOIN metric_batch mb ON ((mb.keyword_norm = r.generated_keyword_norm)));

create or replace view public.feya_v_kw_product_fit_candidates_v1 as
 WITH products AS (
         SELECT p.brief_queue_id,
            p.canonical_product_id,
            NULL::text AS product_slug,
            p.current_title,
            COALESCE(p.h1, p.card_title, p.current_title) AS product_title,
            p.card_title,
            p.h1,
            p.matched_etsy_listing_id,
            p.matched_etsy_listing_id AS source_listing_id,
            p.source_url,
            p.product_type,
            COALESCE((p.safe_compact_payload_json #>> '{product_facts,final_primary_part_v2}'::text[]), (p.safe_compact_payload_json #>> '{product_facts,final_primary_part}'::text[]), (p.safe_compact_payload_json #>> '{product_facts,derived_primary_part}'::text[]), (p.safe_compact_payload_json #>> '{product_facts,final_product_facts,final_primary_part}'::text[])) AS part,
            NULL::text AS part_subtype,
            p.material,
            COALESCE((p.safe_compact_payload_json #>> '{product_facts,final_material_primary_v2}'::text[]), (p.safe_compact_payload_json #>> '{product_facts,final_material_primary}'::text[]), p.normalized_material_primary) AS material_detail,
            p.color,
            COALESCE((p.safe_compact_payload_json #>> '{product_facts,final_color_primary_v2}'::text[]), (p.safe_compact_payload_json #>> '{product_facts,final_color_primary}'::text[]), p.normalized_color_primary) AS color_detail,
                CASE
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'burning man'::text) THEN 'Burning Man'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(festival|rave|edm|edc|coachella|tomorrowland|club)'::text) THEN 'Festival/Rave'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(stage|performance|performer|dance|show|dj|burlesque|drag)'::text) THEN 'Stage/Performance'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(editorial|red carpet|fashion)'::text) THEN 'Fashion/Editorial/Red Carpet'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'cosplay'::text) THEN 'Cosplay'::text
                    ELSE NULL::text
                END AS context_primary,
                CASE
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(cyberpunk|cyber)'::text) THEN 'Cyberpunk'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'futuristic'::text) THEN 'Futuristic'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(desert|dune|apocalyptic|mad max)'::text) THEN 'Desert/Apocalyptic'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(goth|gothic)'::text) THEN 'Goth'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'punk'::text) THEN 'Punk'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(glam|high fashion)'::text) THEN 'Glam/High Fashion'::text
                    ELSE NULL::text
                END AS context_secondary,
                CASE
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'drag'::text) THEN 'drag queen'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'warrior'::text) THEN 'warrior'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'goddess'::text) THEN 'goddess'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'alien'::text) THEN 'alien'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'demon'::text) THEN 'demon'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'angel'::text) THEN 'angel'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ 'queen'::text) THEN 'queen'::text
                    ELSE NULL::text
                END AS persona,
                CASE
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(men|mens|male)'::text) THEN 'male'::text
                    WHEN (lower(((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text))) ~ '(women|womens|female)'::text) THEN 'female'::text
                    ELSE NULL::text
                END AS gender,
            COALESCE((p.safe_compact_payload_json #> '{product_facts,final_product_facts_v2,title_derivation,derived_component_tags}'::text[]), (p.safe_compact_payload_json #> '{product_facts,final_product_facts,title_derivation,derived_component_tags}'::text[]), (p.safe_compact_payload_json #> '{product_facts,derived_product_facts,derived_component_tags}'::text[]), '[]'::jsonb) AS components,
            lower(((((((((((((((((COALESCE(p.current_title, ''::text) || ' '::text) || COALESCE(p.card_title, ''::text)) || ' '::text) || COALESCE(p.h1, ''::text)) || ' '::text) || COALESCE(p.material, ''::text)) || ' '::text) || COALESCE(p.color, ''::text)) || ' '::text) || COALESCE(p.normalized_material_primary, ''::text)) || ' '::text) || COALESCE(p.normalized_color_primary, ''::text)) || ' '::text) || COALESCE((p.raw_ai_context)::text, ''::text)) || ' '::text) || COALESCE((p.safe_compact_payload_json)::text, ''::text))) AS product_text,
            p.keyword_metric_status,
            p.product_fact_quality_status,
            p.product_fact_warning_codes_json,
            p.safe_generation_status,
            p.priority_order,
            now() AS evaluated_at
           FROM feya_commerce_v_product_seo_brief_safe_generation_queue_v1 p
        ), evidence_by_product AS (
         SELECT COALESCE(e.brief_queue_id, p.brief_queue_id) AS brief_queue_id,
            COALESCE(e.canonical_product_id, p.canonical_product_id) AS canonical_product_id,
            e.kw_universe_id,
            e.keyword_norm,
            (count(*))::integer AS evidence_count,
            max((e.axis_json ->> 'keyword_axis'::text)) AS keyword_axis,
            max((e.axis_json ->> 'keyword_pattern'::text)) AS keyword_pattern,
            max(e.target_page_level) AS suggested_page_level,
            bool_or((e.source_code = 'legacy_archive_v33'::text)) AS has_legacy_evidence,
            bool_or((e.source_type = 'metric_request'::text)) AS has_metric_request_evidence,
            jsonb_agg(DISTINCT e.source_code) AS source_codes_json
           FROM (feya_kw_universe_evidence_v1 e
             JOIN products p ON (((e.brief_queue_id = p.brief_queue_id) OR (e.canonical_product_id = p.canonical_product_id))))
          GROUP BY COALESCE(e.brief_queue_id, p.brief_queue_id), COALESCE(e.canonical_product_id, p.canonical_product_id), e.kw_universe_id, e.keyword_norm
        ), latest_metrics AS (
         SELECT DISTINCT ON (feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm) feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm,
            feya_commerce_seo_keyword_metric_snapshots_v1.snapshot_id,
            feya_commerce_seo_keyword_metric_snapshots_v1.avg_monthly_searches,
            feya_commerce_seo_keyword_metric_snapshots_v1.competition,
            feya_commerce_seo_keyword_metric_snapshots_v1.competition_index,
            feya_commerce_seo_keyword_metric_snapshots_v1.fetched_at,
            feya_commerce_seo_keyword_metric_snapshots_v1.data_freshness_status
           FROM (SELECT "snapshot_id", "keyword_norm", "source_api", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_json", "fetched_at", "raw_payload_json", "data_freshness_status", "created_at", "metric_batch_id", "metric_batch_keyword_id", "keyword_id", "source_request_id", "api_version", "ingestion_run_id", "targeting_context_hash", "access_model", "bid_currency_code" FROM public.feya_commerce_seo_keyword_metric_snapshots_v1 WHERE demand_observation_key IS NULL) AS feya_commerce_seo_keyword_metric_snapshots_v1
          ORDER BY feya_commerce_seo_keyword_metric_snapshots_v1.keyword_norm, feya_commerce_seo_keyword_metric_snapshots_v1.fetched_at DESC NULLS LAST, feya_commerce_seo_keyword_metric_snapshots_v1.snapshot_id DESC
        ), metric_batch AS (
         SELECT DISTINCT feya_metric_request_batch_keywords_v1.keyword_norm
           FROM feya_metric_request_batch_keywords_v1
        ), base AS (
         SELECT p.brief_queue_id,
            p.canonical_product_id,
            p.product_slug,
            p.current_title,
            p.product_title,
            p.card_title,
            p.h1,
            p.matched_etsy_listing_id,
            p.source_listing_id,
            p.source_url,
            p.product_type,
            p.part,
            p.part_subtype,
            p.material,
            p.material_detail,
            p.color,
            p.color_detail,
            p.context_primary,
            p.context_secondary,
            p.persona,
            p.gender,
            p.components,
            p.product_text,
            p.keyword_metric_status,
            p.product_fact_quality_status,
            p.product_fact_warning_codes_json,
            p.safe_generation_status,
            p.priority_order,
            p.evaluated_at,
            u.kw_universe_id AS keyword_id,
            u.keyword_text AS keyword,
            u.keyword_norm,
            ep.keyword_axis,
            ep.keyword_pattern,
            ep.suggested_page_level,
            ep.evidence_count,
            u.source_count,
            (lm.snapshot_id IS NOT NULL) AS has_metric_snapshot,
                CASE
                    WHEN (lm.snapshot_id IS NOT NULL) THEN 'has_metric_snapshot'::text
                    WHEN ((mb.keyword_norm IS NOT NULL) OR (u.metric_status = 'needs_metric_validation'::text)) THEN 'wait_for_metrics'::text
                    WHEN COALESCE(ep.has_legacy_evidence, false) THEN 'seed_only_needs_validation'::text
                    ELSE COALESCE(u.metric_status, 'unknown'::text)
                END AS resolved_metric_status,
            COALESCE(ep.source_codes_json, '[]'::jsonb) AS source_codes_json,
            lower(u.keyword_norm) AS kw,
            lower(COALESCE(p.part, ''::text)) AS part_l,
            lower(COALESCE(p.material_detail, ''::text)) AS material_l,
            lower(COALESCE(p.color_detail, ''::text)) AS color_l,
            lower(COALESCE(p.context_primary, ''::text)) AS context_l,
            lower(COALESCE(p.context_secondary, ''::text)) AS context_secondary_l,
            lower(COALESCE(p.persona, ''::text)) AS persona_l,
            lower(COALESCE((p.components)::text, ''::text)) AS components_l
           FROM ((((evidence_by_product ep
             JOIN products p ON (((p.brief_queue_id = ep.brief_queue_id) AND (p.canonical_product_id = ep.canonical_product_id))))
             JOIN feya_kw_universe_v1 u ON ((u.kw_universe_id = ep.kw_universe_id)))
             LEFT JOIN latest_metrics lm ON ((lm.keyword_norm = u.keyword_norm)))
             LEFT JOIN metric_batch mb ON ((mb.keyword_norm = u.keyword_norm)))
        ), scored AS (
         SELECT b.brief_queue_id,
            b.canonical_product_id,
            b.product_slug,
            b.current_title,
            b.product_title,
            b.card_title,
            b.h1,
            b.matched_etsy_listing_id,
            b.source_listing_id,
            b.source_url,
            b.product_type,
            b.part,
            b.part_subtype,
            b.material,
            b.material_detail,
            b.color,
            b.color_detail,
            b.context_primary,
            b.context_secondary,
            b.persona,
            b.gender,
            b.components,
            b.product_text,
            b.keyword_metric_status,
            b.product_fact_quality_status,
            b.product_fact_warning_codes_json,
            b.safe_generation_status,
            b.priority_order,
            b.evaluated_at,
            b.keyword_id,
            b.keyword,
            b.keyword_norm,
            b.keyword_axis,
            b.keyword_pattern,
            b.suggested_page_level,
            b.evidence_count,
            b.source_count,
            b.has_metric_snapshot,
            b.resolved_metric_status,
            b.source_codes_json,
            b.kw,
            b.part_l,
            b.material_l,
            b.color_l,
            b.context_l,
            b.context_secondary_l,
            b.persona_l,
            b.components_l,
                CASE
                    WHEN ((b.kw ~ '(^|[^a-z0-9])latex([^a-z0-9]|$)'::text) AND (b.material_l !~ 'latex'::text)) THEN 'blocked_latex_not_product_truth'::text
                    WHEN (b.kw ~ '(real leather|natural leather|genuine leather)'::text) THEN 'blocked_real_leather_claim'::text
                    WHEN ((b.kw ~ '(real metal|metal armor|metal armour)'::text) AND (b.material_l !~ '(metal|chrome)'::text)) THEN 'blocked_real_metal_claim'::text
                    WHEN ((b.kw ~ '(acrylic|mirror)'::text) AND (b.material_l !~ '(acrylic|mirror)'::text) AND (b.product_text !~ '(acrylic|mirror|breastplate|chest plate)'::text)) THEN 'blocked_acrylic_not_product_truth'::text
                    WHEN ((b.kw ~ '(headpiece|crown|headdress)'::text) AND (b.part_l !~ '(headpiece)'::text) AND (b.components_l !~ '(headpiece|crown|headdress)'::text)) THEN 'blocked_headpiece_not_component'::text
                    WHEN ((b.kw ~ '(^|[^a-z0-9])mask([^a-z0-9]|$)'::text) AND (b.part_l !~ 'mask'::text) AND (b.components_l !~ 'mask'::text)) THEN 'blocked_mask_not_component'::text
                    WHEN (b.kw ~ '(theatre|theater|opera|sports|cultural festival|seasonal peaks)'::text) THEN 'blocked_event_not_canon'::text
                    WHEN ((b.kw ~ 'warrior'::text) AND (COALESCE(b.persona_l, ''::text) <> 'warrior'::text) AND (b.product_text !~ 'warrior'::text)) THEN 'blocked_warrior_not_persona'::text
                    ELSE NULL::text
                END AS blocked_reason,
                CASE
                    WHEN ((b.part_l = 'top'::text) AND (b.kw ~ '(top|corset|bra top|breastplate|chest plate)'::text)) THEN true
                    WHEN ((b.part_l = 'harness'::text) AND (b.kw ~ 'harness'::text)) THEN true
                    WHEN ((b.part_l = 'skirt'::text) AND (b.kw ~ 'skirt'::text)) THEN true
                    WHEN ((b.part_l = 'mask'::text) AND (b.kw ~ 'mask'::text)) THEN true
                    WHEN ((b.part_l = 'headpiece'::text) AND (b.kw ~ '(headpiece|crown|headdress)'::text)) THEN true
                    WHEN ((b.part_l = 'bodysuit'::text) AND (b.kw ~ 'bodysuit'::text)) THEN true
                    WHEN ((b.part_l = 'dress'::text) AND (b.kw ~ 'dress'::text)) THEN true
                    WHEN ((b.part_l = 'shoulders'::text) AND (b.kw ~ '(shoulder|shoulders)'::text)) THEN true
                    WHEN ((b.part_l = 'arms'::text) AND (b.kw ~ '(arm|arms|glove|bracelet|bracer)'::text)) THEN true
                    WHEN ((b.part_l = 'legs'::text) AND (b.kw ~ '(leg|legs|garter|garters)'::text)) THEN true
                    WHEN ((b.components_l ~ '(top|corset|skirt|mask|headpiece|crown|harness|shoulder|arm|leg|garter|glove|choker|belt|panties|bodysuit)'::text) AND (b.kw ~ '(top|corset|skirt|mask|headpiece|crown|harness|shoulder|arm|leg|garter|glove|choker|belt|panties|bodysuit)'::text)) THEN true
                    ELSE false
                END AS part_component_match,
                CASE
                    WHEN ((b.material_l ~ '(mirror acrylic|acrylic)'::text) AND (b.kw ~ '(mirror|acrylic|reflective)'::text)) THEN true
                    WHEN ((b.material_l ~ 'vegan leather'::text) AND (b.kw ~ '(vegan leather|leather|harness)'::text)) THEN true
                    WHEN ((b.material_l ~ 'fabric'::text) AND (b.kw ~ 'fabric'::text)) THEN true
                    ELSE false
                END AS material_match,
                CASE
                    WHEN ((b.color_l <> ''::text) AND (b.kw ~~ (('%'::text || b.color_l) || '%'::text))) THEN true
                    ELSE false
                END AS color_match,
                CASE
                    WHEN ((b.context_l = 'burning man'::text) AND (b.kw ~ 'burning man'::text)) THEN true
                    WHEN ((b.context_l = 'festival/rave'::text) AND (b.kw ~ '(festival|rave|edm|edc|coachella|tomorrowland|club)'::text)) THEN true
                    WHEN ((b.context_l = 'stage/performance'::text) AND (b.kw ~ '(stage|performance|dance|drag|burlesque|show|dj)'::text)) THEN true
                    WHEN ((b.context_l = 'fashion/editorial/red carpet'::text) AND (b.kw ~ '(fashion|editorial|red carpet)'::text)) THEN true
                    WHEN ((b.context_l = 'cosplay'::text) AND (b.kw ~ 'cosplay'::text)) THEN true
                    ELSE false
                END AS context_match,
                CASE
                    WHEN ((b.persona_l <> ''::text) AND (b.kw ~~ (('%'::text || b.persona_l) || '%'::text))) THEN true
                    ELSE false
                END AS persona_match,
                CASE
                    WHEN (b.kw ~ '(outfit|costume|festival|rave|burning man|stage|performance|cosplay|drag|dance)'::text) THEN true
                    ELSE false
                END AS collection_intent,
                CASE
                    WHEN (b.kw ~ '(gold|silver|black|white|red|holographic|mirror|acrylic|vegan leather|leather|metallic|futuristic|cyberpunk|goth|punk)'::text) THEN true
                    ELSE false
                END AS image_alt_intent
           FROM base b
        ), final AS (
         SELECT s.brief_queue_id,
            s.canonical_product_id,
            s.product_slug,
            s.current_title,
            s.product_title,
            s.card_title,
            s.h1,
            s.matched_etsy_listing_id,
            s.source_listing_id,
            s.source_url,
            s.product_type,
            s.part,
            s.part_subtype,
            s.material,
            s.material_detail,
            s.color,
            s.color_detail,
            s.context_primary,
            s.context_secondary,
            s.persona,
            s.gender,
            s.components,
            s.product_text,
            s.keyword_metric_status,
            s.product_fact_quality_status,
            s.product_fact_warning_codes_json,
            s.safe_generation_status,
            s.priority_order,
            s.evaluated_at,
            s.keyword_id,
            s.keyword,
            s.keyword_norm,
            s.keyword_axis,
            s.keyword_pattern,
            s.suggested_page_level,
            s.evidence_count,
            s.source_count,
            s.has_metric_snapshot,
            s.resolved_metric_status,
            s.source_codes_json,
            s.kw,
            s.part_l,
            s.material_l,
            s.color_l,
            s.context_l,
            s.context_secondary_l,
            s.persona_l,
            s.components_l,
            s.blocked_reason,
            s.part_component_match,
            s.material_match,
            s.color_match,
            s.context_match,
            s.persona_match,
            s.collection_intent,
            s.image_alt_intent,
                CASE
                    WHEN (s.blocked_reason IS NOT NULL) THEN 'blocked'::text
                    WHEN (s.part_component_match AND (s.material_match OR s.color_match OR s.context_match OR s.persona_match)) THEN 'strong_fit'::text
                    WHEN s.part_component_match THEN 'medium_fit'::text
                    WHEN (s.collection_intent AND s.context_match) THEN 'collection_fit'::text
                    WHEN (s.image_alt_intent AND (s.material_match OR s.color_match)) THEN 'image_alt_fit'::text
                    ELSE 'needs_review'::text
                END AS fit_status,
                CASE
                    WHEN (s.blocked_reason IS NOT NULL) THEN 0
                    ELSE ((((((
                    CASE
                        WHEN s.part_component_match THEN 40
                        ELSE 0
                    END +
                    CASE
                        WHEN s.material_match THEN 15
                        ELSE 0
                    END) +
                    CASE
                        WHEN s.color_match THEN 15
                        ELSE 0
                    END) +
                    CASE
                        WHEN s.context_match THEN 10
                        ELSE 0
                    END) +
                    CASE
                        WHEN s.persona_match THEN 10
                        ELSE 0
                    END) + LEAST(15, GREATEST(0, COALESCE(s.evidence_count, 0)))) +
                    CASE
                        WHEN (s.product_fact_quality_status = 'HIGH_RISK_FACT_REVIEW'::text) THEN '-10'::integer
                        WHEN (s.product_fact_quality_status = 'FACT_WARNINGS'::text) THEN '-5'::integer
                        ELSE 0
                    END)
                END AS fit_score_pre_metric,
                CASE
                    WHEN (s.blocked_reason IS NOT NULL) THEN 'none'::text
                    WHEN s.part_component_match THEN 'product'::text
                    WHEN s.collection_intent THEN 'collection'::text
                    WHEN s.image_alt_intent THEN 'image_alt'::text
                    ELSE COALESCE(s.suggested_page_level, 'needs_review'::text)
                END AS page_level_recommendation,
                CASE
                    WHEN (s.blocked_reason IS NOT NULL) THEN 'blocked'::text
                    WHEN (s.product_fact_quality_status = ANY (ARRAY['HIGH_RISK_FACT_REVIEW'::text, 'FACT_WARNINGS'::text])) THEN 'needs_fact_review'::text
                    ELSE 'compatible_candidate'::text
                END AS compatibility_status,
            ((s.blocked_reason IS NOT NULL) OR (s.product_fact_quality_status = ANY (ARRAY['HIGH_RISK_FACT_REVIEW'::text, 'FACT_WARNINGS'::text]))) AS needs_human_review
           FROM scored s
        )
 SELECT canonical_product_id,
    product_slug,
    product_title,
    h1,
    card_title,
    source_listing_id,
    matched_etsy_listing_id,
    product_type,
    part,
    part_subtype,
    material,
    material_detail,
    color_detail AS color,
    context_primary,
    context_secondary,
    persona,
    gender,
    components,
    NULL::text AS page_goal,
    keyword_id,
    keyword,
    keyword_norm,
    keyword_axis,
    keyword_pattern,
    suggested_page_level,
    evidence_count,
    source_count,
    has_metric_snapshot,
    resolved_metric_status AS metric_status,
    fit_status,
    fit_score_pre_metric,
    page_level_recommendation,
    compatibility_status,
    blocked_reason,
    needs_human_review,
    jsonb_build_object('part_component_match', part_component_match, 'material_match', material_match, 'color_match', color_match, 'context_match', context_match, 'persona_match', persona_match, 'collection_intent', collection_intent, 'image_alt_intent', image_alt_intent, 'product_fact_quality_status', product_fact_quality_status, 'formula', 'part_component +40, material +15, color +15, context +10, persona +10, evidence up to +15, fact warning -5/-10, blocked=0') AS fit_reason,
    evaluated_at
   FROM final;

create or replace view public.feya_v_manual_keyword_metric_match_v1 as
 WITH latest_metric AS (
         SELECT DISTINCT ON (feya_commerce_seo_keyword_metric_import_staging_v1.keyword_norm) feya_commerce_seo_keyword_metric_import_staging_v1.import_row_id,
            feya_commerce_seo_keyword_metric_import_staging_v1.batch_code,
            feya_commerce_seo_keyword_metric_import_staging_v1.keyword,
            feya_commerce_seo_keyword_metric_import_staging_v1.keyword_norm,
            feya_commerce_seo_keyword_metric_import_staging_v1.geo,
            feya_commerce_seo_keyword_metric_import_staging_v1.language,
            feya_commerce_seo_keyword_metric_import_staging_v1.avg_monthly_searches,
            feya_commerce_seo_keyword_metric_import_staging_v1.competition,
            feya_commerce_seo_keyword_metric_import_staging_v1.competition_index,
            feya_commerce_seo_keyword_metric_import_staging_v1.low_top_of_page_bid,
            feya_commerce_seo_keyword_metric_import_staging_v1.high_top_of_page_bid,
            feya_commerce_seo_keyword_metric_import_staging_v1.imported_at,
            feya_commerce_seo_keyword_metric_import_staging_v1.import_status,
            feya_commerce_seo_keyword_metric_import_staging_v1.import_note
           FROM (SELECT "import_row_id", "batch_code", "keyword", "keyword_norm", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_raw", "source_file_name", "imported_at", "import_status", "import_note", "created_at" FROM public.feya_commerce_seo_keyword_metric_import_staging_v1 WHERE demand_observation_key IS NULL) AS feya_commerce_seo_keyword_metric_import_staging_v1
          WHERE ((feya_commerce_seo_keyword_metric_import_staging_v1.keyword_norm IS NOT NULL) AND (feya_commerce_seo_keyword_metric_import_staging_v1.import_status = ANY (ARRAY['imported'::text, 'ready'::text, 'valid'::text, 'pending'::text, 'new'::text])))
          ORDER BY feya_commerce_seo_keyword_metric_import_staging_v1.keyword_norm, feya_commerce_seo_keyword_metric_import_staging_v1.imported_at DESC NULLS LAST, feya_commerce_seo_keyword_metric_import_staging_v1.import_row_id DESC
        )
 SELECT c.manual_keyword_candidate_id,
    c.brief_queue_id,
    c.canonical_product_id,
    c.source_kw_plan_v2_id,
    c.keyword_text,
    c.keyword_norm,
    c.candidate_status,
    c.metrics_status,
    c.reason_code,
    c.axis_json,
    m.import_row_id,
    m.batch_code,
    m.geo,
    m.language,
    m.avg_monthly_searches,
    m.competition,
    m.competition_index,
    m.low_top_of_page_bid,
    m.high_top_of_page_bid,
    m.imported_at,
        CASE
            WHEN (m.import_row_id IS NULL) THEN 'NO_IMPORTED_METRIC'::text
            ELSE 'HAS_IMPORTED_METRIC'::text
        END AS metric_match_status
   FROM (feya_manual_keyword_candidate_v1 c
     LEFT JOIN latest_metric m ON ((m.keyword_norm = c.keyword_norm)));

create or replace view public.feya_v_metric_import_center_status_v1 as
 SELECT 'combined_export_keywords'::text AS section,
    'NEEDS_EXPORT'::text AS status,
    (count(*))::integer AS rows_count
   FROM feya_v_metric_export_center_keywords_only_v1
UNION ALL
 SELECT 'manual_candidates'::text AS section,
    feya_manual_keyword_candidate_v1.metrics_status AS status,
    (count(*))::integer AS rows_count
   FROM feya_manual_keyword_candidate_v1
  GROUP BY feya_manual_keyword_candidate_v1.metrics_status
UNION ALL
 SELECT 'keyword_plans_v2'::text AS section,
    feya_kw_place_plan_v2.plan_status AS status,
    (count(*))::integer AS rows_count
   FROM feya_kw_place_plan_v2
  GROUP BY feya_kw_place_plan_v2.plan_status
UNION ALL
 SELECT 'metric_staging'::text AS section,
    COALESCE(feya_commerce_seo_keyword_metric_import_staging_v1.import_status, 'unknown'::text) AS status,
    (count(*))::integer AS rows_count
   FROM (SELECT "import_row_id", "batch_code", "keyword", "keyword_norm", "geo", "language", "avg_monthly_searches", "competition", "competition_index", "low_top_of_page_bid", "high_top_of_page_bid", "monthly_search_volumes_raw", "source_file_name", "imported_at", "import_status", "import_note", "created_at" FROM public.feya_commerce_seo_keyword_metric_import_staging_v1 WHERE demand_observation_key IS NULL) AS feya_commerce_seo_keyword_metric_import_staging_v1
  GROUP BY COALESCE(feya_commerce_seo_keyword_metric_import_staging_v1.import_status, 'unknown'::text)
  ORDER BY 1, 2;

CREATE OR REPLACE FUNCTION public.feya_commerce_fn_promote_keyword_metric_import_v1(p_batch_code text)
 RETURNS TABLE(batch_code text, normalized_rows integer, inserted_snapshots integer, updated_staging_rows integer, skipped_rows integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_normalized integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
begin
  update public.feya_commerce_seo_keyword_metric_import_staging_v1 s
  set keyword_norm = lower(trim(s.keyword)),
      import_status = coalesce(nullif(s.import_status, ''), 'pending')
  where s.batch_code = p_batch_code
    and s.demand_observation_key is null
    and (s.keyword_norm is null or btrim(s.keyword_norm) = '')
    and s.keyword is not null;
  get diagnostics v_normalized = row_count;

  insert into public.feya_commerce_seo_keyword_metric_snapshots_v1 (
    keyword_norm,
    source_api,
    geo,
    language,
    avg_monthly_searches,
    competition,
    competition_index,
    low_top_of_page_bid,
    high_top_of_page_bid,
    monthly_search_volumes_json,
    fetched_at,
    raw_payload_json,
    data_freshness_status
  )
  select
    lower(trim(s.keyword_norm)) as keyword_norm,
    'google_ads_csv'::text as source_api,
    coalesce(nullif(s.geo, ''), 'US') as geo,
    coalesce(nullif(s.language, ''), 'en') as language,
    s.avg_monthly_searches,
    nullif(s.competition, '') as competition,
    s.competition_index,
    s.low_top_of_page_bid,
    s.high_top_of_page_bid,
    case
      when s.monthly_search_volumes_raw is not null and btrim(s.monthly_search_volumes_raw) <> ''
        then jsonb_build_object('raw', s.monthly_search_volumes_raw)
      else null::jsonb
    end as monthly_search_volumes_json,
    now() as fetched_at,
    jsonb_build_object(
      'batch_code', s.batch_code,
      'source_file_name', s.source_file_name,
      'import_row_id', s.import_row_id,
      'imported_at', s.imported_at
    ) as raw_payload_json,
    'fresh_manual_import'::text as data_freshness_status
  from public.feya_commerce_seo_keyword_metric_import_staging_v1 s
  where s.batch_code = p_batch_code
    and s.demand_observation_key is null
    and s.keyword_norm is not null
    and btrim(s.keyword_norm) <> ''
    and s.avg_monthly_searches is not null
    and coalesce(s.import_status, 'pending') not in ('promoted_to_snapshots', 'error')
    and not exists (
      select 1
      from public.feya_commerce_seo_keyword_metric_snapshots_v1 m
      where m.keyword_norm = lower(trim(s.keyword_norm))
        and m.demand_observation_key is null
        and m.geo = coalesce(nullif(s.geo, ''), 'US')
        and m.language = coalesce(nullif(s.language, ''), 'en')
        and m.source_api = 'google_ads_csv'
        and m.raw_payload_json ->> 'batch_code' = s.batch_code
    );
  get diagnostics v_inserted = row_count;

  update public.feya_commerce_seo_keyword_metric_import_staging_v1 s
  set import_status = case
        when s.keyword_norm is null or btrim(s.keyword_norm) = '' then 'error'
        when s.avg_monthly_searches is null then 'error'
        else 'promoted_to_snapshots'
      end,
      import_note = case
        when s.keyword_norm is null or btrim(s.keyword_norm) = '' then 'Missing keyword_norm / keyword.'
        when s.avg_monthly_searches is null then 'Missing avg_monthly_searches; row was not promoted.'
        else 'Promoted to metric snapshots by feya_commerce_fn_promote_keyword_metric_import_v1.'
      end
  where s.batch_code = p_batch_code
    and s.demand_observation_key is null
    and coalesce(s.import_status, 'pending') not in ('promoted_to_snapshots', 'error');
  get diagnostics v_updated = row_count;

  select count(*)::int
  into v_skipped
  from public.feya_commerce_seo_keyword_metric_import_staging_v1 s
  where s.batch_code = p_batch_code
    and s.demand_observation_key is null
    and s.import_status = 'error';

  return query select p_batch_code, v_normalized, v_inserted, v_updated, v_skipped;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.feya_fn_apply_manual_keyword_metrics_v1(p_batch_code text DEFAULT NULL::text)
 RETURNS TABLE(updated_rows integer, matched_candidates integer, batch_filter text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_updated integer := 0;
  v_matched integer := 0;
begin
  with latest_metric as (
    select distinct on (s.keyword_norm)
      s.keyword_norm,
      s.batch_code,
      s.geo,
      s.language,
      s.avg_monthly_searches,
      s.competition,
      s.competition_index,
      s.low_top_of_page_bid,
      s.high_top_of_page_bid,
      s.imported_at
    from public.feya_commerce_seo_keyword_metric_import_staging_v1 s
    where s.keyword_norm is not null
      and s.demand_observation_key is null
      and (p_batch_code is null or s.batch_code = p_batch_code)
    order by s.keyword_norm, s.imported_at desc nulls last, s.import_row_id desc
  )
  select count(*)::int into v_matched
  from public.feya_manual_keyword_candidate_v1 c
  join latest_metric m on m.keyword_norm = c.keyword_norm;

  with latest_metric as (
    select distinct on (s.keyword_norm)
      s.keyword_norm,
      s.batch_code,
      s.geo,
      s.language,
      s.avg_monthly_searches,
      s.competition,
      s.competition_index,
      s.low_top_of_page_bid,
      s.high_top_of_page_bid,
      s.imported_at
    from public.feya_commerce_seo_keyword_metric_import_staging_v1 s
    where s.keyword_norm is not null
      and s.demand_observation_key is null
      and (p_batch_code is null or s.batch_code = p_batch_code)
    order by s.keyword_norm, s.imported_at desc nulls last, s.import_row_id desc
  )
  update public.feya_manual_keyword_candidate_v1 c
  set avg_monthly_searches = m.avg_monthly_searches,
      competition = m.competition,
      competition_index = m.competition_index,
      low_top_of_page_bid = m.low_top_of_page_bid,
      high_top_of_page_bid = m.high_top_of_page_bid,
      metric_geo = m.geo,
      metric_language = m.language,
      metric_batch_code = m.batch_code,
      metric_imported_at = coalesce(m.imported_at, now()),
      metrics_status = 'has_metric_import',
      candidate_status = case when c.candidate_status = 'draft' then 'metric_imported' else c.candidate_status end,
      updated_at = now()
  from latest_metric m
  where c.keyword_norm = m.keyword_norm;

  get diagnostics v_updated = row_count;
  return query select v_updated, v_matched, coalesce(p_batch_code, 'ALL_BATCHES');
end;
$function$
;

